window.QuranOfflineData.surahs['026'] = {"metadata":{"surah":26,"name_bn":"আশ-শুআরা","total_ayahs":227,"arabic_source":"qurantexttanzil.csv","translation_source":"QuranEnc","translation_id":"bengali_zakaria","translator":"Dr. Abu Bakr Muhammad Zakaria","translation_version":"1.1.1"},"ayahs":[{"aya":1,"arabic":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ طسم","translation":"ত্বা-সীন-মীম।","footnotes":"২৬- সূরা আশ-শুআরা\n২২৭ আয়াত, মাক্কী।"},{"aya":2,"arabic":"تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ","translation":"এগুলো সুস্পষ্ট কিতাবের আয়াত।","footnotes":""},{"aya":3,"arabic":"لَعَلَّكَ بَاخِعٌ نَّفْسَكَ أَلَّا يَكُونُوا مُؤْمِنِينَ","translation":"তারা মুমিন হচ্ছে না বলে আপনি হয়ত মনোকষ্টে আত্মঘাতী হয়ে পড়বেন।","footnotes":""},{"aya":4,"arabic":"إِن نَّشَأْ نُنَزِّلْ عَلَيْهِم مِّنَ السَّمَاءِ آيَةً فَظَلَّتْ أَعْنَاقُهُمْ لَهَا خَاضِعِينَ","translation":"আমরা ইচ্ছে করলে আসমান থেকে তাদের কাছে এক নিদর্শন নাযিল করতাম, ফলে সেটার প্রতি তাদের ঘাড় বিনত হয়ে পড়ত।","footnotes":""},{"aya":5,"arabic":"وَمَا يَأْتِيهِم مِّن ذِكْرٍ مِّنَ الرَّحْمَنِ مُحْدَثٍ إِلَّا كَانُوا عَنْهُ مُعْرِضِينَ","translation":"আর যখনই তাদের কাছে দয়াময়ের কাছ থেকে কোনো নতুন উপদেশ আসে, তখনই তারা তা থেকে মুখ ফিরিয়ে নেয়।","footnotes":""},{"aya":6,"arabic":"فَقَدْ كَذَّبُوا فَسَيَأْتِيهِمْ أَنبَاءُ مَا كَانُوا بِهِ يَسْتَهْزِئُونَ","translation":"অতএব, তারা তো মিথ্যারোপ করেছে। কাজেই তারা যা নিয়ে ঠাট্টা-বিদ্রূপ করত তার প্রকৃত বার্তা তাদের কাছে শীঘ্রই এসে পড়বে।","footnotes":""},{"aya":7,"arabic":"أَوَلَمْ يَرَوْا إِلَى الْأَرْضِ كَمْ أَنبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ كَرِيمٍ","translation":"তারা কি যমীনের দিকে লক্ষ্য করে না? আমরা তাতে প্ৰত্যেক প্রকারের অনেক উৎকৃষ্ট উদ্ভিদ উদ্গত করেছি [১]!","footnotes":"[১] زَوْجٍ এর শাব্দিক অর্থ হচ্ছে যুগল। এ কারণেই পুরুষ ও স্ত্রী, নর ও নারীকে زَوْجٍ বলা হয়। অনেক বৃক্ষের মধ্যেও নর ও নারী থাকে, সেগুলোকে এদিক দিয়ে زَوْجٍ বলা যায়। কোনো সময় এ শব্দটি বিশেষ প্রকার ও শ্রেণীর অর্থেও ব্যবহৃত হয়। এ হিসাবে বৃক্ষের প্রত্যেক প্রকারকে زَوْجٍ বলা যায়। كَرِيمٍ শব্দের অর্থ উৎকৃষ্ট ও পছন্দনীয় বস্তু। [দেখুন-আদওয়াউল বায়ান, কুরতুবী, ফাতহুল কাদীর]"},{"aya":8,"arabic":"إِنَّ فِي ذَلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","translation":"নিশ্চয় এতে আছে নিদর্শন, আর তাদের অধিকাংশই মুমিন নয়।","footnotes":""},{"aya":9,"arabic":"وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ","translation":"আর নিশ্চয় আপনার রব, তিনি তো পরাক্রমশালী, পরম দয়ালু।","footnotes":""},{"aya":10,"arabic":"وَإِذْ نَادَى رَبُّكَ مُوسَى أَنِ ائْتِ الْقَوْمَ الظَّالِمِينَ","translation":"আর স্মরণ করুন, যখন আপনার রব মূসাকে ডেকে বললেন, ‘আপনি যালিম সম্পপ্রদায়ের কাছে যান,","footnotes":""},{"aya":11,"arabic":"قَوْمَ فِرْعَوْنَ أَلَا يَتَّقُونَ","translation":"‘ফির‘আউনের সম্পপ্রদায়ের কাছে; তারা কি তাকওয়া অবলম্বন করবে না?’","footnotes":""},{"aya":12,"arabic":"قَالَ رَبِّ إِنِّي أَخَافُ أَن يُكَذِّبُونِ","translation":"মূসা বলেছিলেন, ‘হে আমার রব! আমি আশংকা করছি যে, তারা আমার উপর মিথ্যারোপ করবে,","footnotes":""},{"aya":13,"arabic":"وَيَضِيقُ صَدْرِي وَلَا يَنطَلِقُ لِسَانِي فَأَرْسِلْ إِلَى هَارُونَ","translation":"‘এবং আমার বক্ষ সংকুচিত হয়ে পড়ছে, আর আমার জিহ্বা তো সাবলীল নেই। কাজেই হারূনের প্রতিও ওহী পাঠান।","footnotes":""},{"aya":14,"arabic":"وَلَهُمْ عَلَيَّ ذَنبٌ فَأَخَافُ أَن يَقْتُلُونِ","translation":"‘আর আমার বিরুদ্ধে তো তাদের এক অভিযোগ আছে, সুতরাং আমি আশংকা করছি যে, তারা আমাকে হত্যা করবে।’","footnotes":""},{"aya":15,"arabic":"قَالَ كَلَّا فَاذْهَبَا بِآيَاتِنَا إِنَّا مَعَكُم مُّسْتَمِعُونَ","translation":"আল্লাহ্‌ বললেন, ‘না, কখনই নয়, অতএব আপনারা উভয়ে আমাদের নিদর্শনসহ যান, আমরা তো আপনাদের সাথেই আছি, শ্রবণকারী।","footnotes":""},{"aya":16,"arabic":"فَأْتِيَا فِرْعَوْنَ فَقُولَا إِنَّا رَسُولُ رَبِّ الْعَالَمِينَ","translation":"‘অতএব, আপনারা উভয়ে ফির‘আউনের কাছে যান এবং বলুন, ‘আমরা তো সৃষ্টিকুলের রবের রাসূল,","footnotes":""},{"aya":17,"arabic":"أَنْ أَرْسِلْ مَعَنَا بَنِي إِسْرَائِيلَ","translation":"যাতে তুমি আমাদের সাথে যেতে দাও বনী ইসরাইলকে [১]।’","footnotes":"[১] বনী ইসরাঈল ছিল শাম দেশের বাসিন্দা। ফির‘আউন তাদেরকে স্বদেশে যেতে বাধা দিত। এভাবে চার শত বছর ধরে তারা ফির‘আউনের বন্দীশালায় গোলামীর জীবন যাপন করছিল। [দেখুন- বাগভী, কুরতুবী]"},{"aya":18,"arabic":"قَالَ أَلَمْ نُرَبِّكَ فِينَا وَلِيدًا وَلَبِثْتَ فِينَا مِنْ عُمُرِكَ سِنِينَ","translation":"ফির‘আউন বলল, ‘আমরা কি তোমাকে শৈশবে আমাদের মধ্যে লালন-পালন করিনি? আর তুমি তো তোমার জীবনের বহু বছর আমাদের মধ্যে কাটিয়েছ,","footnotes":""},{"aya":19,"arabic":"وَفَعَلْتَ فَعْلَتَكَ الَّتِي فَعَلْتَ وَأَنتَ مِنَ الْكَافِرِينَ","translation":"‘এবং তুমি তোমার কাজ যা করার তা করেছ; তুমি তো অকৃতজ্ঞ।’","footnotes":""},{"aya":20,"arabic":"قَالَ فَعَلْتُهَا إِذًا وَأَنَا مِنَ الضَّالِّينَ","translation":"মূসা বললেন, ‘আমি তো এটা করেছিলাম তখন, যখন আমি ছিলাম বিভ্ৰান্ত’ [২]।","footnotes":"[১] সারকথা এই যে, এ হত্যাকাণ্ড অনিচ্ছাকৃতভাবে হয়েছিল। কাজেই এখানে ضلالة শব্দের অর্থ অজ্ঞাত তথা অনিচ্ছাকৃতভাবে কিবতীর হত্যাকাণ্ড সংঘটিত হওয়া। [ফাতহুল কাদীর, কুরতুবী]"},{"aya":21,"arabic":"فَفَرَرْتُ مِنكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ لِي رَبِّي حُكْمًا وَجَعَلَنِي مِنَ الْمُرْسَلِينَ","translation":"‘তারপর আমি যখন তোমাদের ভয়ে ভীত হলাম তখন আমি তোমাদের কাছ থেকে পালিয়ে গিয়েছিলাম। এরপর আমার রব আমাকে প্রজ্ঞা (নবুওয়ত) দিয়েছেন এবং আমাকে রাসূলদের অন্তর্ভুক্ত করেছেন।","footnotes":""},{"aya":22,"arabic":"وَتِلْكَ نِعْمَةٌ تَمُنُّهَا عَلَيَّ أَنْ عَبَّدتَّ بَنِي إِسْرَائِيلَ","translation":"‘আর আমার প্রতি তোমার যে অনুগ্রহের কথা উল্লেখ করে তুমি দয়া দেখাচ্ছ তা তো এই যে, তুমি বনী ইসরাঈলকে দাসে পরিণত করেছ [১] ।’","footnotes":"[১] অর্থাৎ তোমরা যদি বনী ইসরাঈলের প্রতি জুলুম-নিপীড়ন না চালাতে তাহলে আমি প্রতিপালিত হওয়ার জন্য তোমাদের গৃহে কেন আসতাম? তোমাদের জুলুমের কারণেই তো আমার মা আমাকে ঝুড়িতে ভরে নদীতে ভাসিয়ে দিয়েছিলেন। নয়তো আমার লালন-পালনের জন্য কি আমার নিজের গৃহ ছিল না? তাই এ লালন-পালনের জন্য অনুগৃহীত করার খোঁটা দেয়া তোমার মুখে শোভা পায় না। [দেখুন- কুরতুবী]"},{"aya":23,"arabic":"قَالَ فِرْعَوْنُ وَمَا رَبُّ الْعَالَمِينَ","translation":"ফির‘আউন বলল, ‘সৃষ্টিকুলের রব আবার কী?’","footnotes":""},{"aya":24,"arabic":"قَالَ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ","translation":"মূসা বললেন, ‘তিনি আসমানসমূহ ও যমীন এবং তাদের মধ্যবর্তী সব কিছুর রব, যদি তোমরা নিশ্চিত বিশ্বাসী হও।’","footnotes":""},{"aya":25,"arabic":"قَالَ لِمَنْ حَوْلَهُ أَلَا تَسْتَمِعُونَ","translation":"ফির‘আউন তার আশেপাশের লোকদের লক্ষ করে বলল, ‘তোমরা কি ভাল করে শুনছ না?’","footnotes":""},{"aya":26,"arabic":"قَالَ رَبُّكُمْ وَرَبُّ آبَائِكُمُ الْأَوَّلِينَ","translation":"মূসা বললেন, ‘তিনি তোমাদের রব এবং তোমাদের পূর্বপুরুষদেরও রব।’","footnotes":""},{"aya":27,"arabic":"قَالَ إِنَّ رَسُولَكُمُ الَّذِي أُرْسِلَ إِلَيْكُمْ لَمَجْنُونٌ","translation":"ফির‘আউন বলল, ‘তোমাদের প্রতি প্রেরিত তোমাদের রাসূল তো অবশ্যই পাগল।’","footnotes":""},{"aya":28,"arabic":"قَالَ رَبُّ الْمَشْرِقِ وَالْمَغْرِبِ وَمَا بَيْنَهُمَا إِن كُنتُمْ تَعْقِلُونَ","translation":"মূসা বললেন, ‘তিনি পূর্ব ও পশ্চিমের এবং তাদের মধ্যবর্তী সব কিছুর রব; যদি তোমরা বুঝে থাকো!’","footnotes":""},{"aya":29,"arabic":"قَالَ لَئِنِ اتَّخَذْتَ إِلَهًا غَيْرِي لَأَجْعَلَنَّكَ مِنَ الْمَسْجُونِينَ","translation":"ফির‘আউন বলল, ‘তুমি যদি আমার পরিবর্তে অন্যকে ইলাহরূপে গ্ৰহণ কর আমি তোমাকে অবশ্যই কারারুদ্ধ করব।’","footnotes":""},{"aya":30,"arabic":"قَالَ أَوَلَوْ جِئْتُكَ بِشَيْءٍ مُّبِينٍ","translation":"মূসা বললেন, ‘আমি যদি তোমার কাছে কোনো স্পষ্ট বিষয় নিয়ে আসি, তবুও [১]?’","footnotes":"[১] অর্থাৎ যদি আমি সত্যিই সমগ্র বিশ্ব-জাহানের, আকাশ ও পৃথিবীর এবং পূর্ব ও পশ্চিমের রবের পক্ষ থেকে যে আমাকে পাঠানো হয়েছে এর সপক্ষে সুস্পষ্ট আলামত পেশ করি, তাহলে এ অবস্থায়ও কি আমার কথা মেনে নিতে অস্বীকার করা হবে এবং আমাকে কারাগারে পাঠানো হবে? [দেখুন- বাগভী]"},{"aya":31,"arabic":"قَالَ فَأْتِ بِهِ إِن كُنتَ مِنَ الصَّادِقِينَ","translation":"ফির‘আউন বলল, ‘তুমি যদি সত্যবাদী  হও তবে তা উপস্থিত কর।’","footnotes":""},{"aya":32,"arabic":"فَأَلْقَى عَصَاهُ فَإِذَا هِيَ ثُعْبَانٌ مُّبِينٌ","translation":"তারপর মূসা তাঁর লাঠি নিক্ষেপ করলে তৎক্ষণাৎ তা এক স্পষ্ট অজগরে [১] পরিণত হল।","footnotes":"[১] কুরআন মজীদে কোনো জায়গায় এ জন্য حيّة (সাপ) আবার কোথাও جانّ (ছোট সাপ) শব্দ ব্যবহার করা হয়েছে। আর এখানে বলা হচ্ছে ثعبان (অজগর)। এর ব্যাখ্যা এভাবে করা যায় যে حيّة আরবী ভাষায় সর্পজাতির সাধারণ নাম। তা ছোট সাপও হতে পারে আবার বড় সাপও হতে পারে। আর ثعبان শব্দ ব্যবহার করার কারণ হচ্ছে এই যে, দৈহিক আয়তন ও স্থূলতার দিক দিয়ে তা ছিল অজগরের মতো। অন্যদিকে جان শব্দ ব্যবহার করা হয়েছে ছোট সাপের মতো তার ক্ষীপ্ৰতা ও তেজস্বীতার জন্য। [দেখুন- ফাতহুল কাদীর]"},{"aya":33,"arabic":"وَنَزَعَ يَدَهُ فَإِذَا هِيَ بَيْضَاءُ لِلنَّاظِرِينَ","translation":"আর মূসা তার হাত বের করলে তৎক্ষনাৎ তা দর্শকদের দৃষ্টিতে শুভ্র উজ্জ্বল প্রতিভাত হল।","footnotes":""},{"aya":34,"arabic":"قَالَ لِلْمَلَإِ حَوْلَهُ إِنَّ هَذَا لَسَاحِرٌ عَلِيمٌ","translation":"ফির‘আউন তার আশেপাশের পরিষদবৰ্গকে বলল, ‘এ তো এক সুদক্ষ জাদুকর!","footnotes":""},{"aya":35,"arabic":"يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُم بِسِحْرِهِ فَمَاذَا تَأْمُرُونَ","translation":"‘সে তোমাদেরকে তোমাদের দেশ থেকে তার জাদুবলে বহিস্কৃত করতে চায়। এখন তোমরা কী করতে বল?’","footnotes":""},{"aya":36,"arabic":"قَالُوا أَرْجِهْ وَأَخَاهُ وَابْعَثْ فِي الْمَدَائِنِ حَاشِرِينَ","translation":"তারা বলল, ‘তাকে ও তার ভাইকে কিছু অবকাশ দাও এবং নগরে নগরে  সংগ্রাহকদেরকে পাঠাও,","footnotes":""},{"aya":37,"arabic":"يَأْتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٍ","translation":"‘যেন তারা তোমার কাছে প্রতিটি অভিজ্ঞ জাদুকরকে উপস্থিত করে।’","footnotes":""},{"aya":38,"arabic":"فَجُمِعَ السَّحَرَةُ لِمِيقَاتِ يَوْمٍ مَّعْلُومٍ","translation":"অতঃপর এক নির্ধারিত দিনে নির্দিষ্ট সময়ে জাদুকরদেরকে একত্র করা হল,","footnotes":""},{"aya":39,"arabic":"وَقِيلَ لِلنَّاسِ هَلْ أَنتُم مُّجْتَمِعُونَ","translation":"এবং লোকদেরকে বলা হল, ‘তোমরাও সমবেত হচ্ছে কি?","footnotes":""},{"aya":40,"arabic":"لَعَلَّنَا نَتَّبِعُ السَّحَرَةَ إِن كَانُوا هُمُ الْغَالِبِينَ","translation":"‘যেন আমরা জাদুকরদের অনুসরণ করতে পারি, যদি তারা বিজয়ী হয়।’","footnotes":""},{"aya":41,"arabic":"فَلَمَّا جَاءَ السَّحَرَةُ قَالُوا لِفِرْعَوْنَ أَئِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ الْغَالِبِينَ","translation":"অতঃপর জাদুকরেরা এসে ফির‘আউনকে বলল, ‘আমরা যদি বিজয়ী হই আমাদের জন্য পুরস্কার থাকবে তো?’","footnotes":""},{"aya":42,"arabic":"قَالَ نَعَمْ وَإِنَّكُمْ إِذًا لَّمِنَ الْمُقَرَّبِينَ","translation":"ফির‘আউন বলল, ‘হ্যাঁ, তখন তো তোমরা অবশ্যই আমার ঘনিষ্ঠদের শামিল হবে।’","footnotes":""},{"aya":43,"arabic":"قَالَ لَهُم مُّوسَى أَلْقُوا مَا أَنتُم مُّلْقُونَ","translation":"মূসা তাদেরকে বললেন, ‘তোমরা যা নিক্ষেপ করার তা নিক্ষেপ কর।’","footnotes":""},{"aya":44,"arabic":"فَأَلْقَوْا حِبَالَهُمْ وَعِصِيَّهُمْ وَقَالُوا بِعِزَّةِ فِرْعَوْنَ إِنَّا لَنَحْنُ الْغَالِبُونَ","translation":"অতঃপর তারা তাদের রশি ও লাঠি নিক্ষেপ করল এবং তারা বলল, ‘ফির‘আউনের ইযযতের শপথ! আমরাই তো বিজয়ী হব।’","footnotes":""},{"aya":45,"arabic":"فَأَلْقَى مُوسَى عَصَاهُ فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ","translation":"অতঃপর মূসা তার লাঠি নিক্ষেপ করলেন, সহসা সেটা তাদের অলীক কীর্তিগুলোকে গ্ৰাস করতে লাগল।","footnotes":""},{"aya":46,"arabic":"فَأُلْقِيَ السَّحَرَةُ سَاجِدِينَ","translation":"তখন জাদুকরেরা সাজদাবনত হয়ে পড়ল।","footnotes":""},{"aya":47,"arabic":"قَالُوا آمَنَّا بِرَبِّ الْعَالَمِينَ","translation":"তারা বলল, ‘আমরা ঈমান আনলাম সৃষ্টিকুলের রবের প্রতি---","footnotes":""},{"aya":48,"arabic":"رَبِّ مُوسَى وَهَارُونَ","translation":"‘যিনি মূসা ও হারূনেরও রব।’","footnotes":""},{"aya":49,"arabic":"قَالَ آمَنتُمْ لَهُ قَبْلَ أَنْ آذَنَ لَكُمْ إِنَّهُ لَكَبِيرُكُمُ الَّذِي عَلَّمَكُمُ السِّحْرَ فَلَسَوْفَ تَعْلَمُونَ لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَافٍ وَلَأُصَلِّبَنَّكُمْ أَجْمَعِينَ","translation":"ফির‘আউন বলল, ‘কী! আমি তোমাদেরকে অনুমতি দেয়ার আগেই তোমরা তার প্রতি বিশ্বাস করলে? সে-ই তো তোমাদের প্রধান যে তোমাদেরকে জাদু শিক্ষা দিয়েছে। সুতরাং শীঘ্রই তোমরা এর পরিণাম জানবে। আমি অবশ্যই তোমাদের হাত এবং তোমাদের পা বিপরীত দিক থেকে কেটে ফেলব এবং তোমাদের সবাইকে শূলবিদ্ধ করবই।’","footnotes":""},{"aya":50,"arabic":"قَالُوا لَا ضَيْرَ إِنَّا إِلَى رَبِّنَا مُنقَلِبُونَ","translation":"তারা বলল, ‘কোনো ক্ষতি নেই [১], আমরা তো আমাদের রবের কাছেই প্রত্যাবর্তনকারী।","footnotes":"[১] অর্থাৎ যখন ফির‘আউন জাদুকরদেরকে বিশ্বাস স্থাপনের কারণে হত্যা, হস্ত-পদ কর্তন ও শূলে চড়ানোর হুমকি দিল, তখন জাদুকররা অত্যন্ত তাচ্ছিল্যাভরে জবাব দিল: তুমি যা করতে পার কর। আমাদের কোনো ক্ষতি নেই। আমরা নিহত হলেও পালনকর্তার কাছে পৌঁছে যাব, সেখানের আরামই আরাম। [কুরতুবী, ফাতহুল কাদীর, মুয়াসসার]"},{"aya":51,"arabic":"إِنَّا نَطْمَعُ أَن يَغْفِرَ لَنَا رَبُّنَا خَطَايَانَا أَن كُنَّا أَوَّلَ الْمُؤْمِنِينَ","translation":"আমরা আশা করি যে, আমাদের রব আমাদের অপরাধ ক্ষমা করবেন, কারণ আমরা মুমিনদের মধ্যে অগ্রণী।’","footnotes":""},{"aya":52,"arabic":"وَأَوْحَيْنَا إِلَى مُوسَى أَنْ أَسْرِ بِعِبَادِي إِنَّكُم مُّتَّبَعُونَ","translation":"আর আমরা মূসার প্রতি ওহী করেছিলাম এ মর্মে যে, ‘আমার বান্দাদেরকে নিয়ে রাতে বের হউন [১], অবশ্যই তোমাদের পশ্চাদ্ধাবন করা হবে।’","footnotes":"[১] এক হাদীসে এসেছে, রাসূলুল্লাহ সাল্লাল্লাহু ‘আলাইহি ওয়া সাল্লাম এক বেদুঈনের বাসায় গেলে সে তাঁকে সম্মান করে। রাসূল সাল্লাল্লাহু 'আলাইহি ওয়া সাল্লাম তাকে বললেন: তুমি আমার সাথে সাক্ষাত করতে এসো। বেদুঈন রাসূলের সাথে সাক্ষাত করতে আসলে রাসূল সাল্লাল্লাহু 'আলাইহি ওয়া সাল্লাম বললেন, কিছু চাও? সে বলল: এক উট তার মালামালসহ, আর কিছু ছাগল যা আমার স্ত্রী দোহাতে পারে। তখন রাসূলুল্লাহ সাল্লাল্লাহু 'আলাইহি ওয়া সাল্লাম বললেন, তুমি কি বনী ইসরাঈলের বৃদ্ধার মত হতে পারলে না? সাহাবাগণ জিজ্ঞেস করলেন, বনী ইসরাঈলের বৃদ্ধা, হে আল্লাহ্‌র রাসূল, সে আবার কে? রাসূল সাল্লাল্লাহু 'আলাইহি ওয়া সাল্লাম বললেন, মূসা ‘আলাইহিস সালাম যখন বনী ইসরাঈলদের নিয়ে বের হলেন, তখন পথ হারিয়ে ফেললেন। তিনি বনী ইসরাঈলদের বললেন, কেন এমন হল? তখন তাদের মাঝে আলেমগণ বললেন, ইউসুফ ‘আলাইহিস সালাম মৃত্যুর পূর্বে বনী ইসরাঈল থেকে অঙ্গীকার নিয়েছিলেন যে, বনী ইসরাঈল মিসর ছেড়ে যাওয়ার সময় অবশ্যই তার কফিনের বাক্স সাথে নিয়ে যাবে। আর যেহেতু তা নেয়া হয়নি, সেহেতু পথ হারিয়ে যাচ্ছে। তখন ইউসুফ ‘আলাইহিস সালামের কফিনের সন্ধান করা হল, কেউই তার হদিস দিতে পারল না, শুধু এক বৃদ্ধা ব্যতীত। কিন্তু সে শর্ত সাপেক্ষে বলতে রাজী হল। সে জান্নাতে মূসা ‘আলাইহিস সালামের সাথে থাকার শর্ত দিল। মূসা ‘আলাইহিস সালাম কিছুতেই রাজী হন না। শেষ পর্যন্ত আল্লাহ্‌র নির্দেশে মূসা ‘আলাইহিস সালাম রাজী হলেন। তখন বৃদ্ধা এক এলাকায় সেটা দেখিয়ে দিল। সেখানে পানি ছিল। লোকজন সেই পানি সেঁচে ইউসুফ ‘আলাইহিস সালামের কফিনের বাক্স বের করে আনলে সমস্ত পথ স্পষ্ট হয়ে যায়। [ইবন হিব্বান ৭২৩, মুস্তাদরাকে হাকিম ২/৪০৪-৪০৫, ৫৭১, ৫৭২]"},{"aya":53,"arabic":"فَأَرْسَلَ فِرْعَوْنُ فِي الْمَدَائِنِ حَاشِرِينَ","translation":"তারপর ফির‘আউন শহরে শহরে লোক সংগ্রহকারী পাঠাল,","footnotes":""},{"aya":54,"arabic":"إِنَّ هَؤُلَاءِ لَشِرْذِمَةٌ قَلِيلُونَ","translation":"এ বলে, ‘এরা তো ক্ষুদ্র একটি দল","footnotes":""},{"aya":55,"arabic":"وَإِنَّهُمْ لَنَا لَغَائِظُونَ","translation":"আর তারা তো আমাদের ক্ৰোধ উদ্রেক করেছে;","footnotes":""},{"aya":56,"arabic":"وَإِنَّا لَجَمِيعٌ حَاذِرُونَ","translation":"আর আমরা তো সবাই সদা সতর্ক।’","footnotes":""},{"aya":57,"arabic":"فَأَخْرَجْنَاهُم مِّن جَنَّاتٍ وَعُيُونٍ","translation":"পরিণামে আমরা ফির‘আউন গোষ্ঠীকে বহিষ্কৃত করলাম তাদের উদ্যানরাজি ও প্রস্রবণ হতে","footnotes":""},{"aya":58,"arabic":"وَكُنُوزٍ وَمَقَامٍ كَرِيمٍ","translation":"এবং ধন-ভাণ্ডার ও সুরম্য সৌধমালা হতে।","footnotes":""},{"aya":59,"arabic":"كَذَلِكَ وَأَوْرَثْنَاهَا بَنِي إِسْرَائِيلَ","translation":"এরূপই ঘটেছিল এবং আমরা বনী ইসরাঈলকে করেছিলাম এসবের অধিকারী [১]।","footnotes":"[১] এ আয়াতে বাহ্যতঃ বলা হয়েছে যে, ফির‘আউন সম্প্রদায়ের পরিত্যক্ত সম্পত্তি, বাগ-বাগিচা ও ধন-ভাণ্ডারের মালিক তাদের নিমজ্জিত হওয়ার পর বনী ইসরাঈলকে করে দেয়া হয়। [তাবারী, কুরতুবী] এই ঘটনাটি কুরআনুল কারীমের একাধিক সূরায় ব্যক্ত হয়েছে। যেমন, সূরা আল-আ‘রাফের ১৩৬ ও ১৩৭ নং আয়াতে, সূরা আল-কাসাসের ৫ নং আয়াতে, সূরা আদ-দোখানের ২৫ থেকে ২৮ নং আয়াতসমূহে এবং সূরা আশ-শু'আরার আলোচ্য ৫৯ নং আয়াতে এ ঘটনা উল্লেখিত হয়েছে।"},{"aya":60,"arabic":"فَأَتْبَعُوهُم مُّشْرِقِينَ","translation":"অতঃপর তারা সূর্যোদয়কালে তাদের পিছনে এসে পড়ল।","footnotes":""},{"aya":61,"arabic":"فَلَمَّا تَرَاءَى الْجَمْعَانِ قَالَ أَصْحَابُ مُوسَى إِنَّا لَمُدْرَكُونَ","translation":"অতঃপর যখন দু‘দল পরস্পরকে দেখল, তখন মূসার সঙ্গীরা বলল, ‘আমরা তো ধরা পড়ে গেলাম!’","footnotes":""},{"aya":62,"arabic":"قَالَ كَلَّا إِنَّ مَعِيَ رَبِّي سَيَهْدِينِ","translation":"মূসা বললেন, ‘কখনই নয়! আমার সঙ্গে আছেন আমার রব [১]; সত্বর তিনি আমাকে পথনির্দেশ করবেন।’","footnotes":"[১] পশ্চাদ্ধাবনকারী ফির‘আউনী সৈন্য বাহিনী যখন তাদের সামনে এসে যায়, তখন সমগ্র বনী ইসরাঈল চিৎকার করে উঠল, হায়! আমরা তো ধরা পড়ে গেলাম! আর ধরা পড়ার মধ্যে সন্দেহ ও দেরীই বা কি ছিল, পশ্চাতে অতিবিক্রম সেনাবাহিনী এবং সম্মুখে সমুদ্র-অন্তরায়। এই পরিস্থিতি মূসা ‘আলাইহিস সালামেরও অগোচরে ছিল না। কিন্তু তিনি দৃঢ়তার হিমালয় হয়ে আল্লাহ্‌ তা‘আলার প্রতিশ্রুতিতে দৃঢ় বিশ্বাসী ছিলেন। তিনি তখনো সজোরে বলেন, كَلاَّ আমরা তো ধরা পড়তে পারি না।\n\n إِنَّ مَعِيَ رَبِّي سَيَهْدِينِ \n\nআমার সাথে আমার পালনকর্তা আছেন। তিনি আমাদের পথ বলে দেবেন। [দেখুন-কুরতুবী]"},{"aya":63,"arabic":"فَأَوْحَيْنَا إِلَى مُوسَى أَنِ اضْرِب بِّعَصَاكَ الْبَحْرَ فَانفَلَقَ فَكَانَ كُلُّ فِرْقٍ كَالطَّوْدِ الْعَظِيمِ","translation":"অতঃপর আমরা মূসার প্রতি ওহী করলাম যে, আপনার লাঠি দ্বারা সাগরে আঘাত করুন। ফলে তা বিভক্ত প্ৰত্যেক ভাগ বিশাল পর্বতের মত হয়ে গেল [১];","footnotes":"[১] অৰ্থাৎ পানি উভয় দিকে খুব উচু উঁচু পাহাড়ের মতো দাঁড়িয়ে গিয়েছিল। [কুরতুবী]"},{"aya":64,"arabic":"وَأَزْلَفْنَا ثَمَّ الْآخَرِينَ","translation":"আর আমরা সেখানে কাছে নিয়ে এলাম অন্য দলটিকে,","footnotes":""},{"aya":65,"arabic":"وَأَنجَيْنَا مُوسَى وَمَن مَّعَهُ أَجْمَعِينَ","translation":"এবং আমরা উদ্ধার করলাম মূসা ও তার সঙ্গী সকলকে,","footnotes":""},{"aya":66,"arabic":"ثُمَّ أَغْرَقْنَا الْآخَرِينَ","translation":"তারপর নিমজ্জিত করলাম অন্য দলটিকে।","footnotes":""},{"aya":67,"arabic":"إِنَّ فِي ذَلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","translation":"এতে তো অবশ্যই নিদর্শন রয়েছে, কিন্তু তাদের অধিকাংশই মুমিন নয়।","footnotes":""},{"aya":68,"arabic":"وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ","translation":"আর আপনার রব, তিনি তো পরাক্রমশালী, পরম দয়ালু।","footnotes":""},{"aya":69,"arabic":"وَاتْلُ عَلَيْهِمْ نَبَأَ إِبْرَاهِيمَ","translation":"আর আপনি তাদের কাছে ইবরাহীমের বৃত্তান্ত বর্ণনা করুন।","footnotes":""},{"aya":70,"arabic":"إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِ مَا تَعْبُدُونَ","translation":"যখন তিনি তার পিতা ও তার সম্প্রদায়কে বলেছিলেন, ‘তোমরা কিসের ইবাদাত করা?’","footnotes":""},{"aya":71,"arabic":"قَالُوا نَعْبُدُ أَصْنَامًا فَنَظَلُّ لَهَا عَاكِفِينَ","translation":"তারা বলল, ‘আমরা মূর্তির পূজা করি সুতরাং আমরা নিষ্ঠার সাথে সেগুলোকে আঁকড়ে থাকব।’","footnotes":""},{"aya":72,"arabic":"قَالَ هَلْ يَسْمَعُونَكُمْ إِذْ تَدْعُونَ","translation":"তিনি বললেন, ‘তোমরা যখন আহ্বান কর তখন তারা তোমাদের আহ্বান শোনে কি?’","footnotes":""},{"aya":73,"arabic":"أَوْ يَنفَعُونَكُمْ أَوْ يَضُرُّونَ","translation":"‘অথবা তারা কি তোমাদের উপকার কিংবা অপকার করতে পারে?’","footnotes":""},{"aya":74,"arabic":"قَالُوا بَلْ وَجَدْنَا آبَاءَنَا كَذَلِكَ يَفْعَلُونَ","translation":"তারা বলল, ‘না, তবে আমরা আমাদের পিতৃপুরুষদেরকে পেয়েছি, তারা এরূপই করত।’","footnotes":""},{"aya":75,"arabic":"قَالَ أَفَرَأَيْتُم مَّا كُنتُمْ تَعْبُدُونَ","translation":"ইবরাহীম বললেন, ‘তোমরা কি ভাবে দেখেছ, যাদের ‘ইবাদাত তোমরা করে থাক,","footnotes":""},{"aya":76,"arabic":"أَنتُمْ وَآبَاؤُكُمُ الْأَقْدَمُونَ","translation":"‘তোমরা এবং তোমাদের পূর্ববর্তী পিতৃপুরুষরা!","footnotes":""},{"aya":77,"arabic":"فَإِنَّهُمْ عَدُوٌّ لِّي إِلَّا رَبَّ الْعَالَمِينَ","translation":"সৃষ্টিকুলের রব ব্যতীত এরা সবাই তো আমার শত্ৰু।","footnotes":""},{"aya":78,"arabic":"الَّذِي خَلَقَنِي فَهُوَ يَهْدِينِ","translation":"‘যিনি আমাকে সৃষ্টি করেছেন, অতঃপর তিনিই আমাকে হেদায়াত দিয়েছেন।","footnotes":""},{"aya":79,"arabic":"وَالَّذِي هُوَ يُطْعِمُنِي وَيَسْقِينِ","translation":"আর ‘তিনিই আমাকে খাওয়ান ও পান করান।","footnotes":""},{"aya":80,"arabic":"وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ","translation":"‘এবং রোগাক্রান্ত হলে তিনিই আমাকে আরোগ্য দান করেন [১];","footnotes":"[১] অর্থাৎ আমি যখন অসুস্থ হই, তখন তিনিই আমাকে আরোগ্য দান করেন। এখানে লক্ষণীয় ব্যাপার যে, রোগাক্ৰান্ত হওয়াকে ইবরাহীম ‘আলাইহিস সালাম তার নিজের দিকে সম্পর্কযুক্ত করেছেন, যদিও আল্লাহ্‌র নির্দেশেই সবকিছু হয়। এটাই হল আল্লাহ্‌র সাথে আদাব বা শিষ্টাচার। [দেখুন-বাগভী, কুরতুবী]"},{"aya":81,"arabic":"وَالَّذِي يُمِيتُنِي ثُمَّ يُحْيِينِ","translation":"‘আর তিনিই আমার মৃত্যু ঘটাবেন, তারপর আমাকে পুনর্জীবিত করবেন।","footnotes":""},{"aya":82,"arabic":"وَالَّذِي أَطْمَعُ أَن يَغْفِرَ لِي خَطِيئَتِي يَوْمَ الدِّينِ","translation":"‘এবং যার কাছে আশা করি যে, তিনি কিয়ামতের দিন আমার অপরাধ ক্ষমা করে দেবেন।","footnotes":""},{"aya":83,"arabic":"رَبِّ هَبْ لِي حُكْمًا وَأَلْحِقْنِي بِالصَّالِحِينَ","translation":"‘হে আমার রব! আমাকে প্রজ্ঞা দান করুন এবং সৎকর্মশীলদের সাথে মিলিয়ে দিন।","footnotes":""},{"aya":84,"arabic":"وَاجْعَل لِّي لِسَانَ صِدْقٍ فِي الْآخِرِينَ","translation":"‘আর আমাকে পরবর্তীদের মধ্যে যশস্বী করুন [১],","footnotes":"[১] এ আয়াতের অর্থ এই যে, আল্লাহ্‌ আমাকে এমন সুন্দর তরিকা ও উত্তম নিদর্শন দান করুন, যা কেয়ামত পর্যন্ত মানবজাতি অনুসরণ করে এবং আমাকে উৎকৃষ্ট আলোচনা ও সদগুণাবলী দ্বারা স্মরণ করে। [ফাতহুল কাদীর, বাগভী, কুরতুবী]"},{"aya":85,"arabic":"وَاجْعَلْنِي مِن وَرَثَةِ جَنَّةِ النَّعِيمِ","translation":"‘এবং আমাকে সুখময় জান্নাতের অধিকারীদের অন্তর্ভুক্ত করুন,","footnotes":""},{"aya":86,"arabic":"وَاغْفِرْ لِأَبِي إِنَّهُ كَانَ مِنَ الضَّالِّينَ","translation":"‘আর আমার পিতাকে ক্ষমা করুন, তিনি তো পথভ্রষ্টদের শামিল ছিলেন [১]।","footnotes":"[১] পবিত্র কুরআনের অন্যত্র বলা হয়েছে, \n\nمَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَن يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَىٰ مِن بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ  \n\n‘‘আত্মীয়-স্বজন হলেও মুশরিকদের জন্য ক্ষমা প্রার্থনা করা নবী এবং মু’মিনদের জন্য সংগত নয় যখন এটা সুস্পষ্ট হয়ে গেছে যে, নিশ্চিতই তারা জাহান্নামী।” [সূরা আত-তাওবা ১১৩] কুরআনুল করীমের এই ফরমান জারি হওয়ার পর এখন যার মৃত্যু কুফরের উপর নিশ্চিত ও অবধারিত; তার জন্য মাগফেরাতের দো‘আ করা অবৈধ ও হারাম। কিন্তু এ আয়াতে আল্লাহ্‌ তা‘আলা ইবরাহীম ‘আলাইহিস সালামের দো‘আ উল্লেখ করে বলেছেন:\n\n وَاغْفِرْ لِأَبِي إِنَّهُ كَانَ مِنَ الضَّالِّينَ  \n\n“আর আমার পিতাকে ক্ষমা করে দিন তিনি তো পথভ্রষ্টদের শামিল ছিলেন।” তা থেকে প্রশ্ন দেখা দেয় যে, উপরোক্ত নিষেধাজ্ঞার পর ইবরাহীম ‘আলাইহিস সালাম তার মুশরিক পিতার জন্য কেন মাগফেরাতের দো‘আ করলেন? আল্লাহ্‌ রাব্বুল ‘আলামীন নিজেই কুরআনুল কারীমে এ প্রশ্নের জবাব দিয়েছেন। তিনি বলেন,\n\n وَمَا كَانَ اسْتِغْفَارُ إِبْرَاهِيمَ لِأَبِيهِ إِلَّا عَن مَّوْعِدَةٍ وَعَدَهَا إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُ أَنَّهُ عَدُوٌّ لِّلَّهِ تَبَرَّأَ مِنْهُ ۚ إِنَّ إِبْرَاهِيمَ لَأَوَّاهٌ حَلِيمٌ \n\n-অর্থাৎ “ ইবরাহীম তাঁর পিতার জন্য ক্ষমা প্রার্থনা করেছিলেন, তাকে এর প্রতিশ্রুতি দিয়েছিলেন বলে; তারপর যখন এটা তাঁর কাছে সুস্পষ্ট হল যে, সে আল্লাহ্‌র শত্রু তখন ইবরাহীম তার থেকে নিজেকে বিমুক্ত ঘোষণা করলেন। ইবরাহীম তো কোমল হৃদয় ও সহনশীল।” [সূরা আত-তাওবা ১১৪]"},{"aya":87,"arabic":"وَلَا تُخْزِنِي يَوْمَ يُبْعَثُونَ","translation":"‘এবং আমাকে লাঞ্ছিত করবেন না পুনরুত্থানের দিনে [২]","footnotes":"[২] অর্থাৎ ইবরাহীম ‘আলাইহিস সালাম বললেন, ‘হে আমার রব! যেদিন সমস্ত সৃষ্টিজগতকে পুনরুত্থান করা হবে, সেই কেয়ামতের দিন আমাকে লজ্জিত করবেন না।’ হাদীসে এসেছে, ইবরাহীম আলাইহিস সালাম কেয়ামতের দিন তার পিতা আজরকে তার মুখে ধুলিমলিন কুৎসিত অবস্থায় দেখতে পাবেন। তখন ইবরাহীম ‘আলাইহিস সালাম তাকে বলবেন: আমি কি আপনাকে বলিনি যে, আমার অবাধ্য হবেন না? তখন তার বাবা তাকে বলবেন: আমি আজ তোমার অবাধ্য হব না। তখন ইবরাহীম ‘আলাইহিস সালাম বলবেন: হে রব! আপনি আমাকে পুনরুত্থান দিনে লজ্জিত না করার ওয়াদা করেছেন। আমার পিতার ধ্বংসের চেয়ে লজ্জাজনক ব্যাপার আর কি হতে পারে? তখন আল্লাহ্‌ তা‘আলা বলবেন: আমি কাফেরদের উপর জান্নাত হারাম করে দিয়েছি। তারপর বলা হবে: হে ইবরাহীম! আপনার পায়ের নীচে কি? তখন তিনি তাকালে দেখতে পাবেন বিদঘুটে কুৎসিত হায়েনা জাতীয় এক প্রাণী। তখন তার চার পা ধরে তাকে জাহান্নামে নিক্ষেপ করা হবে। (অর্থাৎ সে এমন ঘৃণিত হবে যে, ইবরাহীম ‘আলাইহিস সালাম তার জন্য কথা বলতে চাইবেন না।) [বুখারী ৩৩৫০]"},{"aya":88,"arabic":"يَوْمَ لَا يَنفَعُ مَالٌ وَلَا بَنُونَ","translation":"‘যে দিন ধন-সম্পদ ও সন্তান-সন্ততি কোনো কাজে আসবে না;","footnotes":""},{"aya":89,"arabic":"إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ","translation":"‘সে দিন উপকৃত হবে শুধু সে, যে আল্লাহ্‌র কাছে আসবে বিশুদ্ধ অন্তঃকরণ নিয়ে।’","footnotes":""},{"aya":90,"arabic":"وَأُزْلِفَتِ الْجَنَّةُ لِلْمُتَّقِينَ","translation":"আর মুত্তাকীদের নিকটবর্তী করা হবে জান্নাত,","footnotes":""},{"aya":91,"arabic":"وَبُرِّزَتِ الْجَحِيمُ لِلْغَاوِينَ","translation":"এবং পথভ্রষ্টদের জন্য উন্মোচিত করা হবে জাহান্নাম [১];","footnotes":"[১] অর্থাৎ একদিকে মুত্তাকিরা জান্নাতে প্রবেশ করার আগেই দেখতে থাকবে, আল্লাহ্‌র মেহেরবানীতে কেমন নিয়ামতে পরিপূর্ণ জায়গায় তারা যাবে। অন্যদিকে পথভ্রষ্টরা তখনো হাশরের ময়দানেই অবস্থান করবে। যে জাহান্নামে তাদের গিয়ে থাকতে হবে তার ভয়াবহ দৃশ্য তাদের সামনে উপস্থাপিত করা হবে। [দেখুন-ফাতহুল কাদীর, কুরতুবী]"},{"aya":92,"arabic":"وَقِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تَعْبُدُونَ","translation":"তাদেরকে বলা হবে, ‘তারা কোথায়, তোমরা যাদের ‘ইবাদাত করতে---","footnotes":""},{"aya":93,"arabic":"مِن دُونِ اللَّهِ هَلْ يَنصُرُونَكُمْ أَوْ يَنتَصِرُونَ","translation":"‘আল্লাহ্‌র পরিবর্তে? তারা কি তোমাদের সাহায্য করতে পারে অথবা তারা কি আত্মরক্ষা করতে সক্ষম?’","footnotes":""},{"aya":94,"arabic":"فَكُبْكِبُوا فِيهَا هُمْ وَالْغَاوُونَ","translation":"অতঃপর তাদেরকে এবং পথ ভ্ৰষ্টকারীদেরকে জাহান্নামে নিক্ষেপ করা হবে অধোমুখী করে [১],","footnotes":"[১] মূলে كُبْكِبُوا শব্দ ব্যবহার করা হয়েছে। এর মধ্যে দু’টি অর্থ নিহিত। এক. একজনের উপর অন্য একজনকে ধাক্কা দিয়ে অধোমুখী করে ফেলে দেয়া হবে। দুই. তারা জাহান্নামের গর্তের তলদেশ পর্যন্ত গড়িয়ে যেতে থাকবে। [দেখুন-কুরতুবী]"},{"aya":95,"arabic":"وَجُنُودُ إِبْلِيسَ أَجْمَعُونَ","translation":"এবং ইবলীসের বাহিনীর সকলকেও।","footnotes":""},{"aya":96,"arabic":"قَالُوا وَهُمْ فِيهَا يَخْتَصِمُونَ","translation":"তারা সেখানে বিতর্কে লিপ্ত হয়ে বলবে,","footnotes":""},{"aya":97,"arabic":"تَاللَّهِ إِن كُنَّا لَفِي ضَلَالٍ مُّبِينٍ","translation":"‘আল্লাহ্‌র শপথ! আমরা তো স্পষ্ট পথভ্রষ্টতায় নিমজ্জিত ছিলাম,’","footnotes":""},{"aya":98,"arabic":"إِذْ نُسَوِّيكُم بِرَبِّ الْعَالَمِينَ","translation":"‘যখন আমরা তোমাদেরকে সৃষ্টিকুলের রবের সমকক্ষ গণ্য করতাম।","footnotes":""},{"aya":99,"arabic":"وَمَا أَضَلَّنَا إِلَّا الْمُجْرِمُونَ","translation":"‘আর আমাদেরকে কেবল দুস্কৃতিকারীরাই পথভ্ৰষ্ট করেছিল;","footnotes":""},{"aya":100,"arabic":"فَمَا لَنَا مِن شَافِعِينَ","translation":"‘অতএব, আমাদের কোনো সুপারিশকারী নেই।","footnotes":""},{"aya":101,"arabic":"وَلَا صَدِيقٍ حَمِيمٍ","translation":"এবং কোনো সহৃদয় বন্ধুও নেই।","footnotes":""},{"aya":102,"arabic":"فَلَوْ أَنَّ لَنَا كَرَّةً فَنَكُونَ مِنَ الْمُؤْمِنِينَ","translation":"‘হায়, যদি আমাদের একবার ফিরে যাওয়ার সুযোগ ঘটত, তাহলে আমরা মুমিনদের অন্তর্ভুক্ত হয়ে যেতাম [১]!’","footnotes":"[১] এ আকাংখার জবাবও কুরআনের এভাবে দেয়া হয়েছে, “যদি তাদেরকে পূর্ববর্তী জীবনে ফিরিয়ে দেয়া হয় তাহলে তারা তাই করতে থাকবে যা করতে তাদেরকে নিষেধ করা হয়েছে।” [সূরা আল-আন‘আম ২৮]"},{"aya":103,"arabic":"إِنَّ فِي ذَلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","translation":"এতে তো অবশ্যই নিদর্শন রয়েছে, কিন্তু তাদের অধিকাংশই মুমিন নয়।","footnotes":""},{"aya":104,"arabic":"وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ","translation":"আর আপনার রব, তিনি তো পরাক্রমশালী, পরম দয়ালু।","footnotes":""},{"aya":105,"arabic":"كَذَّبَتْ قَوْمُ نُوحٍ الْمُرْسَلِينَ","translation":"নূহের সম্প্রদায় রাসূলগণের প্রতি মিথ্যা আরোপ করেছিল।","footnotes":""},{"aya":106,"arabic":"إِذْ قَالَ لَهُمْ أَخُوهُمْ نُوحٌ أَلَا تَتَّقُونَ","translation":"যখন তাদের ভাই নূহ তাদেরকে বলেছিলেন, ‘তোমরা কি তাকওয়া অবলম্বন করবে না?","footnotes":""},{"aya":107,"arabic":"إِنِّي لَكُمْ رَسُولٌ أَمِينٌ","translation":"‘আমি তো তোমাদের জন্য এক বিশ্বস্ত রাসূল।","footnotes":""},{"aya":108,"arabic":"فَاتَّقُوا اللَّهَ وَأَطِيعُونِ","translation":"‘অতএব, তোমরা আল্লাহ্‌র তাকওয়া অবলম্বন কর এবং আমার আনুগত্য কর [১]।","footnotes":"[১] আয়াতটি তাকীদ বা গুরুত্ব প্রকাশের জন্য এবং একথা ব্যক্ত করার জন্য আনা হয়েছে যে, রাসূলের আনুগত্য ও আল্লাহ্‌কে ভয় করার জন্য কেবল রাসূলের বিশ্বস্ততা ও ন্যায়পরায়ণতা অথবা কেবল প্রচারকার্যে প্রতিদান না চাওয়াই যথেষ্ট ছিল। কিন্তু যে রাসূলের মধ্যে সবগুলো গুণই বিদ্যমান আছে, তার আনুগত্য করা ও আল্লাহ্‌কে ভয় করা তো আরো অপরিহার্য হয়ে পড়ে। [ফাতহুল কাদীর]"},{"aya":109,"arabic":"وَمَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِيَ إِلَّا عَلَى رَبِّ الْعَالَمِينَ","translation":"‘আর আমি তোমাদের কাছে এর জন্য কোনো প্রতিদান চাই না; আমার পুরস্কার তো সৃষ্টিকুলের রবের কাছেই আছে।","footnotes":""},{"aya":110,"arabic":"فَاتَّقُوا اللَّهَ وَأَطِيعُونِ","translation":"‘কাজেই তোমরা আল্লাহ্‌র তাকওয়া অবলম্বন কর এবং আমার আনুগত্য কর।’","footnotes":""},{"aya":111,"arabic":"قَالُوا أَنُؤْمِنُ لَكَ وَاتَّبَعَكَ الْأَرْذَلُونَ","translation":"তারা বলল, ‘আমরা কি তোমার প্রতি বিশ্বাস স্থাপন করব অথচ ইতরজনেরা তোমার অনুসরণ করছে?’","footnotes":""},{"aya":112,"arabic":"قَالَ وَمَا عِلْمِي بِمَا كَانُوا يَعْمَلُونَ","translation":"নূহ বললেন, ‘তারা কী করত তা আমার জানার কি দরকার?’","footnotes":""},{"aya":113,"arabic":"إِنْ حِسَابُهُمْ إِلَّا عَلَى رَبِّي لَوْ تَشْعُرُونَ","translation":"‘তাদের হিসেব গ্রহণ তো আমার রবেরই কাজ; যদি তোমরা বুঝতে!","footnotes":""},{"aya":114,"arabic":"وَمَا أَنَا بِطَارِدِ الْمُؤْمِنِينَ","translation":"আর আমি তো ‘মুমিনদেরকে তাড়িয়ে দেয়ার নই।","footnotes":""},{"aya":115,"arabic":"إِنْ أَنَا إِلَّا نَذِيرٌ مُّبِينٌ","translation":"‘আমি তো শুধু একজন স্পষ্ট সতর্ককারী।’","footnotes":""},{"aya":116,"arabic":"قَالُوا لَئِن لَّمْ تَنتَهِ يَا نُوحُ لَتَكُونَنَّ مِنَ الْمَرْجُومِينَ","translation":"তারা বলল, ‘হে নূহ! তুমি যদি নিবৃত্ত না হও তবে তুমি অবশ্যই পাথরের আঘাতে নিহতদের মধ্যে শামিল হবে।’","footnotes":""},{"aya":117,"arabic":"قَالَ رَبِّ إِنَّ قَوْمِي كَذَّبُونِ","translation":"নূহ বললেন, ‘হে আমার রব! আমার সম্প্রদায় তো আমার উপর মিথ্যারোপ করেছে।","footnotes":""},{"aya":118,"arabic":"فَافْتَحْ بَيْنِي وَبَيْنَهُمْ فَتْحًا وَنَجِّنِي وَمَن مَّعِيَ مِنَ الْمُؤْمِنِينَ","translation":"কাজেই আপনি আমার ও তাদের মধ্যে স্পষ্ট মীমাংসা করে দিন এবং আমাকে ও আমার সাথে যেসব মুমিন আছে, তাদেরকে রক্ষা করুন [১]।’","footnotes":"[১] অর্থাৎ নূহ ‘আলাইহিস সালাম দো‘আ করলেন যে, হে আল্লাহ্‌! আপনি আমার ও আমার জাতির মধ্যে ফায়সালা করে দিন এবং আমাকে ও আমার সাখী ঈমানদারদেরকে রক্ষা করুন। [দেখুন-মুয়াসসার] অন্যান্য সূরাসমূহেও নূহ ‘আলাইহিস সালামের এ দো‘আ এবং আল্লাহ্‌র পক্ষ থেকে তার জবাব উল্লেখ করা হয়েছে। যেমন, সূরা আল-কামার ১০-১8।"},{"aya":119,"arabic":"فَأَنجَيْنَاهُ وَمَن مَّعَهُ فِي الْفُلْكِ الْمَشْحُونِ","translation":"অতঃপর আমরা তাকে ও তার সঙ্গে যারা ছিল, তাদেরকে রক্ষা করলাম বোঝাই নৌযানে [১]।","footnotes":"[১] “বোঝাই নৌযান” এর অর্থ হচ্ছে, এ নৌকাটি সকল মু‘মিন ও সকল প্রাণীতে পরিপূর্ণ ছিল। [দেখুন- ফাতহুল কাদীর, সা‘দী] পূর্বেই এ প্রাণীদের এক একটি জোড়া সংগে নেওয়ার জন্য নির্দেশ দেয়া হয়েছিল। এ সম্পর্কে বিস্তারিত দেখুন সূরা হূদ ৪০ আয়াত।"},{"aya":120,"arabic":"ثُمَّ أَغْرَقْنَا بَعْدُ الْبَاقِينَ","translation":"এরপর আমরা বাকী সবাইকে ডুবিয়ে দিলাম।","footnotes":""},{"aya":121,"arabic":"إِنَّ فِي ذَلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","translation":"এতে তো অবশ্যই নিদর্শন রয়েছে, কিন্তু তাদের অধিকাংশই ঈমানদার নয়।","footnotes":""},{"aya":122,"arabic":"وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ","translation":"আর আপনার রব, তিনি তো পরাক্রমশালী, পরম দয়ালু।","footnotes":""},{"aya":123,"arabic":"كَذَّبَتْ عَادٌ الْمُرْسَلِينَ","translation":"‘আদ সম্প্রদায় রাসূলদের প্রতি মিথ্যারোপ করেছিল।","footnotes":""},{"aya":124,"arabic":"إِذْ قَالَ لَهُمْ أَخُوهُمْ هُودٌ أَلَا تَتَّقُونَ","translation":"যখন তাদের ভাই হূদ তাদেরকে বললেন, ‘তোমরা কি তাকওয়া অবলম্বন করবে না?","footnotes":""},{"aya":125,"arabic":"إِنِّي لَكُمْ رَسُولٌ أَمِينٌ","translation":"‘আমি তো তোমাদের জন্য এক বিশ্বস্ত রাসূল।","footnotes":""},{"aya":126,"arabic":"فَاتَّقُوا اللَّهَ وَأَطِيعُونِ","translation":"‘অতএব, তোমরা আল্লাহ্‌র তাকওয়া অবলম্বন কর এবং আমার আনুগত্য কর।","footnotes":""},{"aya":127,"arabic":"وَمَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِيَ إِلَّا عَلَى رَبِّ الْعَالَمِينَ","translation":"‘আর আমি তোমাদের কাছে এর জন্য কোনো প্রতিদান চাই না, আমার পুরস্কার তো সৃষ্টিকুলের রবের কাছেই।","footnotes":""},{"aya":128,"arabic":"أَتَبْنُونَ بِكُلِّ رِيعٍ آيَةً تَعْبَثُونَ","translation":"‘তোমরা কি প্রতিটি উচ্চ স্থানে [১] স্তম্ভ নির্মাণ করছ নিরর্থক [২]?","footnotes":"[১] ইবন আব্বাস রাদিয়াল্লাহু ‘আনহুমার মতে رِيعٍ উচ্চ স্থানকে বলা হয়। মুজাহিদ ও অনেক তাফসীরবিদের মতে رِيعٍ দুই পাহাড়ের মধ্যবর্তী পথকে বলা হয়। [কুরতুবী]\n\n[২] ايَةً এর আসল অর্থ নিদর্শন। এস্থলে সুউচ্চ স্মৃতিসৌধ বোঝানো হয়েছে। تَعۡبَثُونَ শব্দটি عبث থেকে উদ্ভূত। এর অর্থ অযথা বা যাতে কোনো প্রকার উপকার নেই। এখানে অর্থ এই যে, তারা অযথা সুউচ্চ অট্টালিকা নির্মাণ করত, যার কোনো প্রয়োজন ছিল না। এতে শুধু গৰ্ব করাই উদ্দেশ্য থাকত। [ইবন কাসীর]"},{"aya":129,"arabic":"وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمْ تَخْلُدُونَ","translation":"‘আর তোমরা প্রাসাদসমূহ [১] নির্মাণ করছ যেন তোমরা স্থায়ী হবে [২]।","footnotes":"[১] مَصَانِعَ শব্দটি مِصْنَعٌ এর বহুবচন। কাতাদাহ বলেন, مَصَانِعَ বলে পানির চৌবাচ্চা বোঝানো হয়েছে; কিন্তু মুজাহিদ বলেন যে, এখানে সুদৃঢ় প্রাসাদ বোঝানো হয়েছে। [ইবন কাসীর]\n\n[২] لَعَكَّكُمْ تَخْلُدُوْنَ ইমাম বুখারী সহীহ বুখারীতে বর্ণনা করেন যে, এখানে لعل শব্দটি تشبيه অর্থাৎ উদাহরণ অর্থে ব্যবহৃত হয়েছে। ইবন আব্বাস এর অনুবাদে বলেন, كَأَنَّكُمْ تَخْلُدُوْنَ -অর্থাৎ যেন তোমরা চিরকাল থাকবে। [কুরতুবী]"},{"aya":130,"arabic":"وَإِذَا بَطَشْتُم بَطَشْتُمْ جَبَّارِينَ","translation":"আর যখন তোমরা আঘাত হান তখন আঘাত হেনে থাক স্বেচ্ছাচারী হয়ে।","footnotes":""},{"aya":131,"arabic":"فَاتَّقُوا اللَّهَ وَأَطِيعُونِ","translation":"সুতরাং তোমরা আল্লাহ্‌র তাকওয়া অবলম্বন কর এবং আমার আনুগত্য কর।","footnotes":""},{"aya":132,"arabic":"وَاتَّقُوا الَّذِي أَمَدَّكُم بِمَا تَعْلَمُونَ","translation":"আর তোমরা তাঁর তাকওয়া অবলম্বন কর যিনি তোমাদেরকে দান করেছেন সে সমুদয়, যা তোমরা জান।","footnotes":""},{"aya":133,"arabic":"أَمَدَّكُم بِأَنْعَامٍ وَبَنِينَ","translation":"তিনি তোমাদেরকে দান করেছেন চতুস্পদ জন্তু ও পুত্ৰ সন্তান,","footnotes":""},{"aya":134,"arabic":"وَجَنَّاتٍ وَعُيُونٍ","translation":"এবং উদ্যান ও প্রস্রবণ;","footnotes":""},{"aya":135,"arabic":"إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ","translation":"‘আমি তো তোমাদের জন্য আশংকা করি মহাদিনের শাস্তির।’","footnotes":""},{"aya":136,"arabic":"قَالُوا سَوَاءٌ عَلَيْنَا أَوَعَظْتَ أَمْ لَمْ تَكُن مِّنَ الْوَاعِظِينَ","translation":"তারা বলল, ‘তুমি উপদেশ দাও বা না-ই দাও, উভয়ই আমাদের জন্য সমান।","footnotes":""},{"aya":137,"arabic":"إِنْ هَذَا إِلَّا خُلُقُ الْأَوَّلِينَ","translation":"‘এটা তো কেবল পূর্ববর্তীদেরই স্বভাব।","footnotes":""},{"aya":138,"arabic":"وَمَا نَحْنُ بِمُعَذَّبِينَ","translation":"‘আমরা মোটেই শাস্তিপ্রাপ্ত হবো না।’","footnotes":""},{"aya":139,"arabic":"فَكَذَّبُوهُ فَأَهْلَكْنَاهُمْ إِنَّ فِي ذَلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","translation":"সুতরাং তারা তার প্রতি মিথ্যারোপ করল ফলে আমরা তাদেরকে ধ্বংস করলাম। এতে তো অবশ্যই আছে নিদর্শন; কিন্তু তাদের অধিকাংশই মুমিন নয় [১]।","footnotes":"[১] আল্লাহ্‌ তা‘আলা বলেছেন যে, তারা তাদের নবী হুদ আলাইহিস সালামের উপর মিথ্যারোপ করেছিল, ফলে আল্লাহ্‌ তাদেরকে ধ্বংস করে দিয়েছেন। [ইবন কাসীর]"},{"aya":140,"arabic":"وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ","translation":"আর আপনার রব, তিনি তো পরাক্রমশালী, পরম দয়ালু।","footnotes":""},{"aya":141,"arabic":"كَذَّبَتْ ثَمُودُ الْمُرْسَلِينَ","translation":"সামূদ সম্প্রদায় রাসূলগণের প্রতি মিথ্যারোপ করেছিল।","footnotes":""},{"aya":142,"arabic":"إِذْ قَالَ لَهُمْ أَخُوهُمْ صَالِحٌ أَلَا تَتَّقُونَ","translation":"যখন তাদের ভাই সালিহ তাদেরকে বললেন, ‘তোমরা কি তাকওয়া অবলম্বন করবে না?","footnotes":""},{"aya":143,"arabic":"إِنِّي لَكُمْ رَسُولٌ أَمِينٌ","translation":"‘আমি তো তোমাদের জন্য এক বিশ্বস্ত রাসূল।","footnotes":""},{"aya":144,"arabic":"فَاتَّقُوا اللَّهَ وَأَطِيعُونِ","translation":"সুতরাং তোমরা আল্লাহ্‌র তাকওয়া অবলম্বন কর এবং আমার আনুগত্য কর,","footnotes":""},{"aya":145,"arabic":"وَمَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِيَ إِلَّا عَلَى رَبِّ الْعَالَمِينَ","translation":"‘আর আমি তোমাদের কাছে এর জন্য কোনো প্রতিদান চাই না, আমার প্রতিদান তো সৃষ্টিকুলের রবের কাছেই আছে।","footnotes":""},{"aya":146,"arabic":"أَتُتْرَكُونَ فِي مَا هَاهُنَا آمِنِينَ","translation":"‘তোমাদেরকে কি নিরাপদ অবস্থায় ছেড়ে রাখা হবে, যা এখানে আছে তাতে-","footnotes":""},{"aya":147,"arabic":"فِي جَنَّاتٍ وَعُيُونٍ","translation":"‘উদ্যানে, প্রস্রবণে","footnotes":""},{"aya":148,"arabic":"وَزُرُوعٍ وَنَخْلٍ طَلْعُهَا هَضِيمٌ","translation":"‘ও শস্যক্ষেত্রে এবং সুকোমল গুচ্ছ বিশিষ্ট খেজুর বাগানে?","footnotes":""},{"aya":149,"arabic":"وَتَنْحِتُونَ مِنَ الْجِبَالِ بُيُوتًا فَارِهِينَ","translation":"‘আর তোমরা নৈপুণ্যের সাথে পাহাড় কেটে ঘর নির্মাণ করছ।","footnotes":""},{"aya":150,"arabic":"فَاتَّقُوا اللَّهَ وَأَطِيعُونِ","translation":"সুতরাং তোমরা আল্লাহ্‌র তাকওয়া অবলম্বন কর এবং আমার আনুগত্য কর","footnotes":""},{"aya":151,"arabic":"وَلَا تُطِيعُوا أَمْرَ الْمُسْرِفِينَ","translation":"আর তোমরা সীমালংঘনকারীদের নির্দেশের আনুগত্য করো না;","footnotes":""},{"aya":152,"arabic":"الَّذِينَ يُفْسِدُونَ فِي الْأَرْضِ وَلَا يُصْلِحُونَ","translation":"‘যারা যমীনে বিপর্যয় সৃষ্টি করে এবং সংশোধন করে না।’","footnotes":""},{"aya":153,"arabic":"قَالُوا إِنَّمَا أَنتَ مِنَ الْمُسَحَّرِينَ","translation":"তারা বলল, ‘তুমি তো জাদুগ্ৰস্তাদের অন্যতম।","footnotes":""},{"aya":154,"arabic":"مَا أَنتَ إِلَّا بَشَرٌ مِّثْلُنَا فَأْتِ بِآيَةٍ إِن كُنتَ مِنَ الصَّادِقِينَ","translation":"‘তুমি তো আমাদের মতই একজন মানুষ, কাজেই তুমি যদি সত্যবাদী হও তবে একটি নিদর্শন উপস্থিত কর।’","footnotes":""},{"aya":155,"arabic":"قَالَ هَذِهِ نَاقَةٌ لَّهَا شِرْبٌ وَلَكُمْ شِرْبُ يَوْمٍ مَّعْلُومٍ","translation":"সালিহ বললেন, ‘এটা একটা উষ্ট্ৰী, এর জন্য আছে পানি পানের পালা এবং তোমাদের জন্য আছে নির্ধারিত দিনে পানি পানের পালা;","footnotes":""},{"aya":156,"arabic":"وَلَا تَمَسُّوهَا بِسُوءٍ فَيَأْخُذَكُمْ عَذَابُ يَوْمٍ عَظِيمٍ","translation":"‘আর তোমরা এর কোনো অনিষ্ট সাধন করো না; করলে মহাদিনের শাস্তি তোমাদের উপর আপতিত হবে।’","footnotes":""},{"aya":157,"arabic":"فَعَقَرُوهَا فَأَصْبَحُوا نَادِمِينَ","translation":"অতঃপর তারা সেটাকে হত্যা করল, পরিণামে তারা অনুতপ্ত হল।","footnotes":""},{"aya":158,"arabic":"فَأَخَذَهُمُ الْعَذَابُ إِنَّ فِي ذَلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","translation":"অতঃপর শাস্তি তাদেরকে গ্ৰাস করল। এতে অবশ্যই রয়েছে নিদর্শন, কিন্তু তাদের অধিকাংশই মুমিন নয়।","footnotes":""},{"aya":159,"arabic":"وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ","translation":"আর আপনার রব, তিনি তো পরাক্রমশালী, পরম দয়ালু।","footnotes":""},{"aya":160,"arabic":"كَذَّبَتْ قَوْمُ لُوطٍ الْمُرْسَلِينَ","translation":"লূতের সম্প্রদায় রাসূলগণের প্রতি মিথ্যারোপ করেছিল,","footnotes":""},{"aya":161,"arabic":"إِذْ قَالَ لَهُمْ أَخُوهُمْ لُوطٌ أَلَا تَتَّقُونَ","translation":"যখন তাদের ভাই লূত তাদেরকে বললেন, ‘তোমরা কি তাকওয়া অবলম্বন করবে না?","footnotes":""},{"aya":162,"arabic":"إِنِّي لَكُمْ رَسُولٌ أَمِينٌ","translation":"‘আমি তো তোমাদের জন্য এক বিশ্বস্ত রাসূল।","footnotes":""},{"aya":163,"arabic":"فَاتَّقُوا اللَّهَ وَأَطِيعُونِ","translation":"‘কাজেই তোমরা আল্লাহ্‌র তাকওয়া অবলম্বন কর এবং আমার আনুগত্য কর।","footnotes":""},{"aya":164,"arabic":"وَمَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِيَ إِلَّا عَلَى رَبِّ الْعَالَمِينَ","translation":"‘আর আমি এর জন্য তোমাদের কাছে কোনো প্রতিদান চাই না, আমার প্রতিদান তো সৃষ্টিকুলের রবের কাছেই আছে।","footnotes":""},{"aya":165,"arabic":"أَتَأْتُونَ الذُّكْرَانَ مِنَ الْعَالَمِينَ","translation":"‘সৃষ্টিকুলের মধ্যে তো তোমরাই কি পুরুষের সাথে উপগত হও?","footnotes":""},{"aya":166,"arabic":"وَتَذَرُونَ مَا خَلَقَ لَكُمْ رَبُّكُم مِّنْ أَزْوَاجِكُم بَلْ أَنتُمْ قَوْمٌ عَادُونَ","translation":"‘আর তোমাদের রব তোমাদের জন্য যে স্ত্রীগণকে সৃষ্টি করেছেন তাদেরকে তোমরা বর্জন করে থাক। বরং তোমরা তো এক সীমালংঘনকারী সম্প্রদায়।’","footnotes":""},{"aya":167,"arabic":"قَالُوا لَئِن لَّمْ تَنتَهِ يَا لُوطُ لَتَكُونَنَّ مِنَ الْمُخْرَجِينَ","translation":"তারা বলল, ‘হে লূত! তুমি যদি নিবৃত্ত না হও, তবে অবশ্যই তুমি নির্বাসিত হবে।’","footnotes":""},{"aya":168,"arabic":"قَالَ إِنِّي لِعَمَلِكُم مِّنَ الْقَالِينَ","translation":"লূত বললেন, ‘আমি অবশ্যই তোমাদের এ কাজের ঘৃণাকারী।","footnotes":""},{"aya":169,"arabic":"رَبِّ نَجِّنِي وَأَهْلِي مِمَّا يَعْمَلُونَ","translation":"‘হে আমার রব! আমাকে এবং আমার পরিবার-পরিজনকে, তারা যা করে তা থেকে রক্ষা করুন।’","footnotes":""},{"aya":170,"arabic":"فَنَجَّيْنَاهُ وَأَهْلَهُ أَجْمَعِينَ","translation":"তারপর আমরা তাকে এবং তার পরিবার-পরিজনকে সকলকে রক্ষা করলাম।","footnotes":""},{"aya":171,"arabic":"إِلَّا عَجُوزًا فِي الْغَابِرِينَ","translation":"এক বৃদ্ধা ছাড়া [১], যে ছিল পিছনে অবস্থানকারীদের অন্তর্ভুক্ত।","footnotes":"[১] এখানে عَخُوز বলে লূত ‘আলাইহিস সালামের স্ত্রীকে বোঝানো হয়েছে। সে কওমে লূতের এই কুকর্মে সম্মত ছিল এবং কাফের ছিল। সূরা আত-তাহরীমে নূহ ও লুত আলাইহিমাস সালামের স্ত্রীদের সম্পর্কে বলা হয়েছে: “এ মহিলা দু’টি আমার দু’জন সৎ বান্দার গৃহে ছিল। কিন্তু তারা তাঁদের সাথে বিশ্বাসঘাতকতা করে।” [সূরা আত-তাহরীম ১০] অর্থাৎ তারা উভয়ই ছিল ঈমান শূন্য এবং নিজেদের সৎ স্বামীদের সাথে সহযোগিতা করার পরিবর্তে তারা তাদের কাফের জাতির সহযোগী হয়। এজন্য আল্লাহ্‌ যখন লূতের জাতির উপর আযাব নাযিল করার ফায়সালা করলেন এবং লূতকে নিজের পরিবার-পরিজনদের নিয়ে এ এলাকা ত্যাগ করার হুকুম দিলেন তখন সাথে সাথে নিজের স্ত্রীকে সংগে না নেয়ার হুকুমও দিলেন: “কাজেই কিছু রাত থাকতেই আপনি নিজের পরিবার-পরিজনদেরকে সাথে নিয়ে বের হয়ে যান এবং আপনাদের কেউ যেন পেছন ফিরে না তাকায়। কিন্তু আপনার স্ত্রীকে সংগে করে নিয়ে যাবেন না। তাদের ভাগ্যে যা ঘটবে তারও তাই ঘটবে।’’ [সূরা হূদ ৮১]"},{"aya":172,"arabic":"ثُمَّ دَمَّرْنَا الْآخَرِينَ","translation":"তারপর আমরা অপর সকলকে ধ্বংস করলাম।","footnotes":""},{"aya":173,"arabic":"وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا فَسَاءَ مَطَرُ الْمُنذَرِينَ","translation":"আর আমরা তাদের উপর শাস্তি মূলক বৃষ্টি বর্ষণ করেছিলাম, ভীতি প্রদর্শিতদের জন্য এ বৃষ্টি ছিল কত নিকৃষ্ট [১]!","footnotes":"[১] কোনো কোনো মুফাসসিরের মতে, এ বৃষ্টি বলতে এখানে পানির বৃষ্টি বুঝানো হয়নি, বরং পাথর বৃষ্টির কথা বুঝানো হয়েছে। [দেখুন-তবারী, মুয়াসসার]"},{"aya":174,"arabic":"إِنَّ فِي ذَلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","translation":"এতে তো অবশ্যই নিদর্শন রয়েছে, কিন্তু তাদের অধিকাংশই মুমিন নয়।","footnotes":""},{"aya":175,"arabic":"وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ","translation":"আর আপনার রব, তিনি তো পরাক্রমশালী, পরম দয়ালু।","footnotes":""},{"aya":176,"arabic":"كَذَّبَ أَصْحَابُ الْأَيْكَةِ الْمُرْسَلِينَ","translation":"আইকাবাসীরা [১] রাসূলগণের প্রতি মিথ্যারোপ করেছিল,","footnotes":"[১] ইউসুফ ‘আলাইহিস সালামের পরে আল্লাহ্‌ তা‘আলা শু‘আইব ‘আলাইহিস সালামকে পাঠান। তার জাতি ছিল মাদইয়ান জাতি। [সূরা আল-আ‘রাফ ৮৫] মাদইয়ান ছিল শু‘আইব ‘আলাইহিস সালামের জাতির এক পূর্বপুরুষের নাম। অপরদিকে কখনো কখনো পবিত্ৰ কুরআনে শুয়াইব ‘আলাইহিস সালামের কওম সম্পর্কে বলা হয়েছে, ‘আসহাবুল আইকাহ’ বা গাছওয়ালাগণ। [সূরা আশ-শুয়ারা ১৭৬] অধিকাংশ মুফাসসিরদের মতে আইকাবাসী দ্বারা মাদইয়ান জাতিকে বুঝানো হয়েছে। [আদওয়া আল-বায়ান]"},{"aya":177,"arabic":"إِذْ قَالَ لَهُمْ شُعَيْبٌ أَلَا تَتَّقُونَ","translation":"যখন শু‘আইব তাদেরকে বলেছিলেন, ‘তোমরা কি তাকওয়া অবলম্বন করবে না?","footnotes":""},{"aya":178,"arabic":"إِنِّي لَكُمْ رَسُولٌ أَمِينٌ","translation":"আমি তো তোমাদের জন্য এক বিশ্বস্ত রাসূল।","footnotes":""},{"aya":179,"arabic":"فَاتَّقُوا اللَّهَ وَأَطِيعُونِ","translation":"‘কাজেই তোমরা আল্লাহ্‌র তাকওয়া অবলম্বন কর এবং আমার আনুগত্য কর।","footnotes":""},{"aya":180,"arabic":"وَمَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِيَ إِلَّا عَلَى رَبِّ الْعَالَمِينَ","translation":"‘আর আমি তোমাদের কাছে এর জন্য কোনো প্রতিদান চাই না। আমার পুরস্কার তো সৃষ্টিকুলের রবের কাছেই আছে।","footnotes":""},{"aya":181,"arabic":"أَوْفُوا الْكَيْلَ وَلَا تَكُونُوا مِنَ الْمُخْسِرِينَ","translation":"‘মাপে পূর্ণ মাত্রায় দেবে; আর যারা মাপে কম দেয় তোমরা তাদের অন্তর্ভুক্ত হয়ো না","footnotes":""},{"aya":182,"arabic":"وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَقِيمِ","translation":"‘এবং ওজন করবে সঠিক দাঁড়িপাল্লায়।","footnotes":""},{"aya":183,"arabic":"وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ","translation":"‘আর লোকদেরকে তাদের প্রাপ্য বস্তু কম দিও না এবং পৃথিবীতে বিপর্যয় সৃষ্টি করে বেড়িও না।","footnotes":""},{"aya":184,"arabic":"وَاتَّقُوا الَّذِي خَلَقَكُمْ وَالْجِبِلَّةَ الْأَوَّلِينَ","translation":"আর তাঁর তাকওয়া অবলম্বন কর যিনি তোমাদেরকে ও তোমাদের আগে যারা গত হয়েছে তাদেরকে সৃষ্টি করেছেন।’","footnotes":""},{"aya":185,"arabic":"قَالُوا إِنَّمَا أَنتَ مِنَ الْمُسَحَّرِينَ","translation":"তারা বলল, ‘তুমি তো জাদুগ্ৰস্তাদের অন্তর্ভুক্ত;","footnotes":""},{"aya":186,"arabic":"وَمَا أَنتَ إِلَّا بَشَرٌ مِّثْلُنَا وَإِن نَّظُنُّكَ لَمِنَ الْكَاذِبِينَ","translation":"‘আর তুমি তো আমাদের মতই একজন মানুষ, আমরা তো তোমাকে মিথ্যাবাদীদের অন্তর্ভুক্ত মনে করি।","footnotes":""},{"aya":187,"arabic":"فَأَسْقِطْ عَلَيْنَا كِسَفًا مِّنَ السَّمَاءِ إِن كُنتَ مِنَ الصَّادِقِينَ","translation":"‘সুতরাং তুমি যদি সত্যবাদী হও তবে আকাশের এক খণ্ড আমাদের উপর ফেলে দাও।’","footnotes":""},{"aya":188,"arabic":"قَالَ رَبِّي أَعْلَمُ بِمَا تَعْمَلُونَ","translation":"তিনি বললেন, ‘আমার রব ভাল করে জানেন তোমরা যা কর।’","footnotes":""},{"aya":189,"arabic":"فَكَذَّبُوهُ فَأَخَذَهُمْ عَذَابُ يَوْمِ الظُّلَّةِ إِنَّهُ كَانَ عَذَابَ يَوْمٍ عَظِيمٍ","translation":"সুতরাং তারা তার প্রতি মিথ্যারোপ করল, ফলে তাদেরকে মেঘাচ্ছন্ন দিনের শাস্তি গ্রাস করল [১]। এ তো ছিল এক ভীষণ দিনের শাস্তি!","footnotes":"[১] এই আয়াতের ঘটনা এই যে, আল্লাহ্‌ তা‘আলা এই সম্প্রদায়ের উপর তীব্র গরম চাপিয়ে দেন। ফলে তারা গৃহের ভেতরে ও বাইরে কোথাও শান্তি পেত না। এরপর তিনি তাদের নিকটবর্তী এক মাঠের উপর গাঢ় কালো মেঘ প্রেরণ করেন। এই মেঘের নীচে সুশীতল বায়ু ছিল। গরমে অস্থির সম্প্রদায় দৌড়ে দৌড়ে এই মেঘের নীচে জমায়েত হয়ে গেল, তখন তাদের উপর আল্লাহ্‌র সুনির্ধারিত শাস্তি এসে গেল। আর তাতে তারা সবাই ধ্বংস হয়ে গেল। [মুয়াসসার]"},{"aya":190,"arabic":"إِنَّ فِي ذَلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","translation":"এতে তো অবশ্যই রয়েছে নিদর্শন [১], আর তাদের অধিকাংশই মুমিন নয়।","footnotes":"[১] শু‘আইব ‘আলাইহিস সালামের জাতির ধ্বংসের কথা পবিত্র কুরআনে বিভিন্নভাবে এসেছে। এর কারণ হল, শু‘আইব ‘আলাইহিস সালামের জাতির অপরাধ ছিল বিভিন্ন প্রকার। প্রত্যেক প্রকার অপরাধের জন্য তাদের শাস্তি হয়েছিল। সুতরাং আল্লাহ্‌ তা‘আলা যখন তাদের কোনো অপরাধের কথা উল্লেখ করেছেন, তখন সেখানে সে অপরাধ মোতাবেক শাস্তির কথাও উল্লেখ করেছেন। যেমন সূরা আশ-শু‘আরায় এসেছে, তারা বলেছিল: তুমি যদি সত্যবাদী হও তবে আমাদের জন্য আকাশের টুকরা ফেলে দাও। এর জবাবে আল্লাহ্‌ তা‘আলা তাদের শাস্তির কথা উল্লেখ করে বলেন, তাদেরকে ছায়ার দিনে শাস্তি পেয়ে বসল। [সূরা আশ-শু‘আরা ১৮৯] যা তাদের দাবীর সাথে সামঞ্জস্যপূর্ণ। সূরা আল-আ‘রাফের ৮৮ নং আয়াতে তারা শু‘আইব ‘আলাইহিস সালাম ও তার সাথীদেরকে এমন ভয় দেখাল যে, তারা কেঁপে উঠেছিল। তারা বলেছিল: “হে শু‘আইব! আমরা তোমাকে এবং যারা তোমার উপর ঈমান এনেছে তাদেরকে আমাদের জনপদ থেকে বের করে দেব অথবা তোমরা আমাদের দলে ফিরে আসবে।” তাদের এ কথার জবাবে আল্লাহ্‌ তা‘আলা তাদের শাস্তির কথা উল্লেখ করে বলেছেন, “তাদেরকে পেয়ে বসল কম্পন।” [সূরা আল-আ‘রাফ ৯১] কিন্তু সূরা হূদের ৮৭ নং আয়াতে তারা শু‘আইব ‘আলাইহিস সালামের সালাত নিয়ে ঠাট্টা করে তাকে অপমান করেছিল। সে ঠাট্টার জবাবে আল্লাহ্‌ তা‘আলা তাদের শাস্তি হিসাবে বলেছেন, “তাদেরকে পেয়ে বসল চিৎকার।” [সূরা হুদ ৯৪]"},{"aya":191,"arabic":"وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ","translation":"আর আপনার রব, তিনি তো পরাক্রমশালী, পরম দয়ালু।","footnotes":""},{"aya":192,"arabic":"وَإِنَّهُ لَتَنزِيلُ رَبِّ الْعَالَمِينَ","translation":"আর নিশ্চয় এটা (আল-কুরআন) সৃষ্টিকুলের রব হতে নাযিলকৃত।","footnotes":""},{"aya":193,"arabic":"نَزَلَ بِهِ الرُّوحُ الْأَمِينُ","translation":"বিশ্বস্ত রূহ (জিবরাঈল) তা নিয়ে নাযিল হয়েছেন।","footnotes":""},{"aya":194,"arabic":"عَلَى قَلْبِكَ لِتَكُونَ مِنَ الْمُنذِرِينَ","translation":"আপনার হৃদয়ে, যাতে আপনি সতর্ককারীদের অন্তর্ভুক্ত হতে পারেন।","footnotes":""},{"aya":195,"arabic":"بِلِسَانٍ عَرَبِيٍّ مُّبِينٍ","translation":"সুস্পষ্ট আরবী ভাষায় [১]।","footnotes":"[১] আয়াত থেকে জানা গেল যে, আরবী ভাষায় লিখিত কুরআনই কুরআন। অন্য যে কোনো ভাষায় কুরআনের কোনো বিষয়বস্তুর অনুবাদকে কুরআন বলা হবে না। [দেখুন- ইবন কাসীর]"},{"aya":196,"arabic":"وَإِنَّهُ لَفِي زُبُرِ الْأَوَّلِينَ","translation":"আর পূর্ববর্তী কিতাবসমূহে অবশ্যই এর উল্লেখ আছে।","footnotes":""},{"aya":197,"arabic":"أَوَلَمْ يَكُن لَّهُمْ آيَةً أَن يَعْلَمَهُ عُلَمَاءُ بَنِي إِسْرَائِيلَ","translation":"বনী ইসরাইলের আলেমগণ এ সম্পর্কে জানে---এটা কি তাদের জন্য নিদর্শন নয় [১]?","footnotes":"[১] অর্থাৎ বনী ইসরাঈলের আলেমরা একথা জানে যে, কুরআন মজীদে যে শিক্ষা দেয়া হয়েছে তা ঠিক সেই একই শিক্ষা যা পূর্ববর্তী আসমানী কিতাবগুলোতে দেয়া হয়েছিল। মক্কাবাসীরা কিতাবের জ্ঞান না রাখলেও আশেপাশের এলাকায় বনী ইসরাঈলের বিপুল সংখ্যক আলেম ও বিদ্বান রয়েছে। তারা জানে, মুহাম্মাদ ইবন আবদুল্লাহ আজ প্রথমবার তাদের সামনে কোনো অভিনব ও অদ্ভুত “কথা” রাখেননি বরং হাজার হাজার বছর থেকে আল্লাহ্‌র নবীগণ এই একই কথা বারবার এনেছেন। এ নাযিলকৃত বিষয়ও সেই একই রব্বুল আলমীনের পক্ষ থেকে এসেছে যিনি পূর্ববর্তী কিতাবগুলো নাযিল করেছিলেন, এ কথাটি কি এ বিষয়ে নিশ্চিন্ততা অর্জন করার জন্য যথেষ্ট নয়? [দেখুন-ফাতহুল কাদীর]"},{"aya":198,"arabic":"وَلَوْ نَزَّلْنَاهُ عَلَى بَعْضِ الْأَعْجَمِينَ","translation":"আর আমরা যদি এটা কোনো অনারবের উপর নাযিল করতাম","footnotes":""},{"aya":199,"arabic":"فَقَرَأَهُ عَلَيْهِم مَّا كَانُوا بِهِ مُؤْمِنِينَ","translation":"এবং এটা সে তাদের কাছে পাঠ করত, তবে তারা তাতে ঈমান আনত না;","footnotes":""},{"aya":200,"arabic":"كَذَلِكَ سَلَكْنَاهُ فِي قُلُوبِ الْمُجْرِمِينَ","translation":"এভাবে আমরা সেটা অপরাধীদের অন্তরে সঞ্চার করেছি [১]।","footnotes":"[১] এ আয়াতের কাছাকাছি আয়াত সূরা আল-হিজরের ১২ নং আয়াতেও এসেছে। সেখানে এর অর্থ বর্ণনা করা হয়েছে। মূলতঃ অনেকেই এর অর্থ এভাবে বর্ণনা করেছেন: “আমরা এভাবে মিথ্যাপ্রতিপন্ন করা, কুফরী করা, অস্বীকার করা এবং সীমালঙ্ঘন করাকে অপরাধীদের অন্তরে প্রবেশ করিয়ে দেই, তারা হক্ক এর প্রতি ঈমান আনবে না।” আরবী ভাষায় سلك শব্দের অর্থ হচ্ছে কোনো জিনিসকে অন্য জিনিসের মধ্যে ঢুকিয়ে দেয়া, অনুপ্রবেশ করানো, চালিয়ে দেয়া বা গলিয়ে দেয়া। যেমন সুঁইয়ের ছিদ্রে সূতো গলিয়ে দেয়া হয়। কাজেই এ আয়াতের অর্থ এটাও হতে পারে যে, অপরাধীদের অন্তরে এ কুরআন বারুদের মত আঘাত করে এবং তা শুনে তাদের মনে এমন আগুন জ্বলে ওঠে যেন মনে হয় একটি গরম শলাকা তাদের বুকে বিদ্ধ হয়ে এফোঁড় ওফোঁড় করে দিয়েছে। সুতরাং তারা এটা সহ্য করতে পারবে না, এর উপর ঈমানও আনবে না। [দেখুন-ফাতহুল কাদীর]"},{"aya":201,"arabic":"لَا يُؤْمِنُونَ بِهِ حَتَّى يَرَوُا الْعَذَابَ الْأَلِيمَ","translation":"তারা এতে ঈমান আনবে না যতক্ষণ না তারা যন্ত্রণাদায়ক শাস্তি দেখতে পাবে;","footnotes":""},{"aya":202,"arabic":"فَيَأْتِيَهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ","translation":"সুতরাং তা তাদের কাছে এসে পড়বে হঠাৎ করে; অথচ তারা কিছুই উপলব্ধি করতে পারবে না।","footnotes":""},{"aya":203,"arabic":"فَيَقُولُوا هَلْ نَحْنُ مُنظَرُونَ","translation":"তখন তারা বলবে, ‘আমাদেরকে কি অবকাশ দেয়া হবে?’","footnotes":""},{"aya":204,"arabic":"أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ","translation":"তারা কি তবে আমাদের শাস্তি ত্বরান্বিত করতে চায়?","footnotes":""},{"aya":205,"arabic":"أَفَرَأَيْتَ إِن مَّتَّعْنَاهُمْ سِنِينَ","translation":"আপনি ভেবে দেখুন, যদি আমরা তাদেরকে দীর্ঘকাল ভোগ-বিলাস করতে দেই [১],","footnotes":"[১] এ আয়াতে ইঙ্গিত আছে যে, দুনিয়াতে দীর্ঘ জীবন লাভ করাও আল্লাহ্‌ তা‘আলার একটি নেয়ামত। কিন্তু যারা এই নেয়ামতের না-শোকরী করে, বিশ্বাস স্থাপন করে না, তাদের দীর্ঘ জীবনের নিরাপত্তা ও অবকাশ কোনো কাজে আসবে না। আর এজন্যই রাসূল সাল্লাল্লাহু ‘আলাইহি ওয়া সাল্লামের এক হাদীসে এসেছে, তিনি বলেছেন, কিয়ামতের দিন কাফেরকে নিয়ে এসে জাহান্নামে এক প্রকার চুবিয়ে আনার পর তাকে জিজ্ঞাসা করা হবে, তুমি কি তোমার জীবনে কখনো ভাল কিছু পেয়েছ? সে বলবে: হে প্ৰভূ! আপনার শপথ, কখনো পাইনি। অপরদিকে দুনিয়ার সবচেয়ে দূৰ্ভাগা ব্যাক্তিকে নিয়ে জান্নাতে প্রবেশ করিয়ে তাকে জিজ্ঞাসা করা হবে তুমি কি দুনিয়াতে কখনো কষ্ট পেয়েছ? সে বলবে, আপনার শপথ, হে আমার প্রভূ! কখনো নয়। [মুসলিম ২৮০৭]"},{"aya":206,"arabic":"ثُمَّ جَاءَهُم مَّا كَانُوا يُوعَدُونَ","translation":"তারপর তাদেরকে যে বিষয়ে সতর্ক করা হয়েছিল তা তাদের কাছে এসে পড়ে,","footnotes":""},{"aya":207,"arabic":"مَا أَغْنَى عَنْهُم مَّا كَانُوا يُمَتَّعُونَ","translation":"তখন যা তাদের ভোগ-বিলাসের উপকরণ হিসেবে দেয়া হয়েছিল তা তাদের কি উপকারে আসবে?","footnotes":""},{"aya":208,"arabic":"وَمَا أَهْلَكْنَا مِن قَرْيَةٍ إِلَّا لَهَا مُنذِرُونَ","translation":"আর আমরা এমন কোনো জনপদ ধ্বংস করিনি যার জন্য সতর্ককারী ছিল না [১];","footnotes":"[১] অর্থাৎ আমি কোনো জনপদ ধ্বংস করে দেয়ার পূর্বে সতর্ককারী ছিল, তাদের স্মরণ করিয়ে দেয়ার জন্য, আমি যালেম নই। আল্লাহ্‌ তা‘আলা বিনা অপরাধে কাউকে শাস্তি দেন না। সে জন্য তিনি যুগে যুগে সতর্ককারী নবী-রাসূল পাঠিয়েছেন। [দেখুন-মুয়াসসার] অনুরূপ আয়াত আরো দেখুন- সূরা আল-ইসরা ১৫, সূরা আল-কাসাস ৫৯]"},{"aya":209,"arabic":"ذِكْرَى وَمَا كُنَّا ظَالِمِينَ","translation":"(তাদের জন্য) স্মরণ হিসেবে, আর আমরা যুলুমকারী নই,","footnotes":""},{"aya":210,"arabic":"وَمَا تَنَزَّلَتْ بِهِ الشَّيَاطِينُ","translation":"আর শয়তানরা এটাসহ নাযিল হয়নি।","footnotes":""},{"aya":211,"arabic":"وَمَا يَنبَغِي لَهُمْ وَمَا يَسْتَطِيعُونَ","translation":"আর তারা এ কাজের যোগ্যও নয় এবং তারা এর সামর্থ্যও রাখে না।","footnotes":""},{"aya":212,"arabic":"إِنَّهُمْ عَنِ السَّمْعِ لَمَعْزُولُونَ","translation":"তাদেরকে তো শোনার সুযোগ হতে দূরে রাখা হয়েছে।","footnotes":""},{"aya":213,"arabic":"فَلَا تَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ فَتَكُونَ مِنَ الْمُعَذَّبِينَ","translation":"অতএব আপনি অন্য কোনো ইলাহকে আল্লাহ্‌র সাথে ডাকবেন না, ডাকলে আপনি শাস্তিপ্রাপ্তদের অন্তর্ভুক্ত হবেন।","footnotes":""},{"aya":214,"arabic":"وَأَنذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ","translation":"আর আপনার নিকটস্থ জ্ঞাতি-গোষ্ঠীকে সতর্ক করুন।","footnotes":""},{"aya":215,"arabic":"وَاخْفِضْ جَنَاحَكَ لِمَنِ اتَّبَعَكَ مِنَ الْمُؤْمِنِينَ","translation":"এবং যারা আপনার অনুসরণ করে সেসব মুমিনদের প্রতি আপনার পক্ষপুট অবনত করে দিন।","footnotes":""},{"aya":216,"arabic":"فَإِنْ عَصَوْكَ فَقُلْ إِنِّي بَرِيءٌ مِّمَّا تَعْمَلُونَ","translation":"অতঃপর তারা যদি আপনার অবাধ্য হয় তাহলে আপনি বলুন, ‘তোমরা যা কর নিশ্চয় আমি তা থেকে দায়মুক্ত।’","footnotes":""},{"aya":217,"arabic":"وَتَوَكَّلْ عَلَى الْعَزِيزِ الرَّحِيمِ","translation":"আর আপনি নির্ভর করুন পরাক্রমশালী, পরম দয়ালু আল্লাহ্‌র উপর,","footnotes":""},{"aya":218,"arabic":"الَّذِي يَرَاكَ حِينَ تَقُومُ","translation":"যিনি আপনাকে দেখেন যখন আপনি দাঁড়ান [১],","footnotes":"[১] এ আয়াতের তাফসীরে কয়েকটি বর্ণনা এসেছে- \n\n(এক) আপনি একমাত্র আল্লাহ্‌র উপরই ভরসা করুন যিনি আপনার হেফাজত করবেন, আপনার সাহায্য-সহযোগিতা করবেন। যেমনটি অন্য আয়াতে বলা হয়েছে- “আপনি আপনার প্রভূর নির্দেশের উপর ধৈর্য ধারণ করুন, কারণ আপনি আমাদের হেফাজতে রয়েছেন। আমাদের চক্ষুর সামনেই আছেন। [সূরা আত-তূর ৪৮] \n\n(দুই) ইবন আব্বাস বলেন, যিনি আপনাকে দেখেন যখন আপনি সালাতে দাঁড়ান। \n\n(তিন) ইকরামা বলেন, যিনি তার কিয়াম, রুকূ‘, সাজদা ও বসা দেখেন। \n\n(চার) কাতাদাহ বলেন, সালাতে দেখেন, যখন একা সালাত আদায় করেন এবং যখন জামা‘আতে অন্যদের সাথে সালাত আদায় করেন। এটা ইকরামা, হাসান বসরী, আতা প্রমূখেরও মত। [দেখুন-ইবন কাসীর, কুরতুবী, বাগভী]"},{"aya":219,"arabic":"وَتَقَلُّبَكَ فِي السَّاجِدِينَ","translation":"এবং সাজদাকারীদের মাঝে আপনার উঠাবসা [১]।","footnotes":"[১] এর কয়েকটি অর্থ হতে পারে। এক. আপনি যখন জামায়াতের সাথে সালাত পড়ার সময় নিজের মুকতাদীদের সাথে উঠা-বসা ও রুকূ’-সাজদা করেন তখন আল্লাহ্‌ আপনাকে দেখতে থাকেন। দুই. রাতের বেলা উঠে যখন নিজের সাথীরা (যাদের বৈশিষ্ট্যসূচক গুণ হিসেবে “সাজদাকারী” শব্দ ব্যবহৃত হয়েছে) তাদের আখেরাত গড়ার জন্য কেমন তৎপরতা চালিয়ে যাচ্ছে তা দেখার উদ্দেশ্যে ঘোরাফেরা করতে থাকেন তখন আপনি আল্লাহ্‌র দৃষ্টির আড়ালে থাকেন না। তিন. আপনি নিজের সাজদাকারী সাথীদেরকে সংগে নিয়ে আল্লাহ্‌র বান্দাদের সংশোধন করার জন্য যেসব প্রচেষ্টা ও সংগ্রাম চালিয়ে যাচ্ছেন আল্লাহ্‌ তা অবগত আছেন। চার. সাজদাকারী লোকদের দলে আপনার যাবতীয় তৎপরতা আল্লাহ্‌র নজরে আছে। তিনি জানেন আপনি কিভাবে তাদের প্রশিক্ষণ দিচ্ছেন, কিভাবে ও কেমন পর্যায়ে তাদের আত্মশুদ্ধি করছেন এবং কিভাবে ভেজাল সোনাকে খাঁটি সোনায় পরিণত করছেন। [দেখুন-তবারী, বাগভী]"},{"aya":220,"arabic":"إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ","translation":"তিনি তো সর্বশ্রোতা, সর্বজ্ঞ।","footnotes":""},{"aya":221,"arabic":"هَلْ أُنَبِّئُكُمْ عَلَى مَن تَنَزَّلُ الشَّيَاطِينُ","translation":"তোমাদেরকে কি আমি জানাব কার কাছে শয়তানরা নাযিল হয়?","footnotes":""},{"aya":222,"arabic":"تَنَزَّلُ عَلَى كُلِّ أَفَّاكٍ أَثِيمٍ","translation":"তারা তো নাযিল হয় প্রত্যেকটি ঘোর মিথ্যাবাদী ও পাপীর কাছে।","footnotes":""},{"aya":223,"arabic":"يُلْقُونَ السَّمْعَ وَأَكْثَرُهُمْ كَاذِبُونَ","translation":"তারা কান পেতে থাকে এবং তাদের অধিকাংশই মিথ্যাবাদী [১]।","footnotes":"[১] এর দু’টি অর্থ হতে পারে। একটি হচ্ছে, শয়তানরা কিছু শুনে নিয়ে নিজেদের চেলাদেরকে জানিয়ে দেয় এবং তাতে সামান্যতম সত্যের সাথে বিপুল পরিমাণ মিথ্যার মিশ্রণ ঘটায়। দ্বিতীয় অর্থ হচ্ছে, মিথ্যুক-প্রতারক গণকরা শয়তানের কাছ থেকে কিছু শুনে নেয় এবং তারপর তার সাথে নিজের পক্ষ থেকে অনেকটা মিথ্যা মিশিয়ে মানুষের কানে ফুঁকে দিতে থাকে। [দেখুন-ফাতহুল কাদীর] একটি হাদীসে এর আলোচনা এসেছে। আয়েশা রাদিয়াল্লাহু ‘আনহা বলেন, কোনো কোনো লোক নবী সাল্লাল্লাহু আলাইহি ওয়া সাল্লামকে গণকদের ব্যাপারে জিজ্ঞেস করে। জবাবে তিনি বলেন, এসব কিছুই নয়। তারা বলে, হে আল্লাহ্‌র রাসূল! কখনো কখনো তারা তো আবার ঠিক সত্যি কথাই বলে দেয়। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম জবাবে বলেন, সত্যি কথাটা কখনো কখনো জিনেরা নিয়ে আসে এবং তাদের বন্ধুদের কানে ফুঁকে দেয় তারপর তারা তার সাথে শত মিথ্যার মিশ্রণ ঘটিয়ে একটি কাহিনী তৈরী করে। [বুখারী ৩২১০]"},{"aya":224,"arabic":"وَالشُّعَرَاءُ يَتَّبِعُهُمُ الْغَاوُونَ","translation":"আর কবিগণ, তাদের অনুসরণ তো বিভ্ৰান্তরাই করে।","footnotes":""},{"aya":225,"arabic":"أَلَمْ تَرَ أَنَّهُمْ فِي كُلِّ وَادٍ يَهِيمُونَ","translation":"আপনি কি দেখেন না যে, ওরা উদভ্ৰান্ত হয়ে প্রত্যেক উপত্যকায় ঘুরে বেড়ায়?","footnotes":""},{"aya":226,"arabic":"وَأَنَّهُمْ يَقُولُونَ مَا لَا يَفْعَلُونَ","translation":"এবং তারা তো বলে এমন কথা, যা তারা করে না।","footnotes":""},{"aya":227,"arabic":"إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَذَكَرُوا اللَّهَ كَثِيرًا وَانتَصَرُوا مِن بَعْدِ مَا ظُلِمُوا وَسَيَعْلَمُ الَّذِينَ ظَلَمُوا أَيَّ مُنقَلَبٍ يَنقَلِبُونَ","translation":"কিন্তু তারা ছাড়া যারা ঈমান এনেছে, সৎকাজ করেছে, আল্লাহ্‌কে বেশী পরিমাণ স্মরণ করেছে এবং অত্যাচারিত হওয়ার পর প্রতিশোধ গ্ৰহণ করেছে। আর যালিমরা শীঘ্রই ফিরে যাবে জানবে কোন ধরনের গন্তব্যস্থলে তারা ফিরে যাবে।","footnotes":""}]};
